// ══════════════════════════════════════════════════════════════
// Formatter idempotency tests
// ══════════════════════════════════════════════════════════════

/// Format a .gg fixture twice and assert the second pass produces the same
/// output as the first (idempotency). Uses the library API directly.
///
/// Post-Round XXXV Track C3 Stage 0 (fmt-fix chip): fixtures that FAIL to
/// parse are correctly refused by the formatter, not silently dropped. Those
/// fixtures pin a REJECT class (parse or check), NOT formatter idempotence;
/// skip them here — the reject fixtures are exercised by their own tests.
fn assert_fmt_idempotent(fixture: &str) {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture_path = manifest_dir.join("tests/fixtures").join(fixture);

    let source = std::fs::read_to_string(&fixture_path)
        .unwrap_or_else(|e| panic!("Cannot read {}: {e}", fixture_path.display()));

    let first = match gorget::formatter::format_source_result(&source) {
        Ok(s) => s,
        Err(_) => {
            // Fixture pins a REJECT class — not the FMT idempotence layer.
            // Silently skip (its own test binds the reject).
            return;
        }
    };
    let second = gorget::formatter::format_source_infallible(&first);

    assert_eq!(
        first, second,
        "Formatter is NOT idempotent for {fixture}.\n\
         === First pass ===\n{first}\n\
         === Second pass ===\n{second}"
    );
}

/// Guard for the formatter data-loss class: `gg fmt` output MUST round-trip
/// (re-parse with zero parse errors) AND be idempotent (a second pass is
/// byte-identical, losing no code).
///
/// History: long binary-op chains (`a + a + ... + a`) used to break into a
/// bare leading-operator continuation form (`a\n        + a\n        + a`),
/// which the parser REJECTS — and a second `gg fmt` pass then silently DROPPED
/// the orphaned `+ a` lines, LOSING code on round-trip. The fix wraps broken
/// chains in parentheses (`(a\n        + a)`), the only multi-line form the
/// lexer accepts (NEWLINE is suppressed only inside brackets). This guard
/// makes that whole class non-silently-reopenable: any formatter output that
/// fails to re-parse, or that changes on a second pass, fails here.
fn assert_fmt_round_trips(label: &str, source: &str) {
    use gorget::parser::Parser;

    // Pass 1: format the source.
    let first = gorget::formatter::format_source_infallible(source);

    // Round-trip: the formatted output MUST re-parse cleanly. A leading-operator
    // continuation (the old data-loss bug) shows up here as parse errors.
    let mut p1 = Parser::new(&first);
    let _ = p1.parse_module();
    assert!(
        p1.errors.is_empty(),
        "Formatter output for `{label}` does NOT re-parse \
         ({} parse error(s)) — this is the data-loss class.\n\
         === Formatted (pass 1) ===\n{first}\n=== First parse error ===\n{:?}",
        p1.errors.len(),
        p1.errors.first(),
    );

    // Idempotence: a second pass must be byte-identical (nothing dropped/reshaped).
    let second = gorget::formatter::format_source_infallible(&first);
    assert_eq!(
        first, second,
        "Formatter is NOT idempotent for `{label}`.\n\
         === First pass ===\n{first}\n=== Second pass ===\n{second}"
    );

    // The second pass must also still re-parse cleanly (belt-and-suspenders:
    // catches a fixpoint that converged onto an invalid shape).
    let mut p2 = Parser::new(&second);
    let _ = p2.parse_module();
    assert!(
        p2.errors.is_empty(),
        "Second formatter pass for `{label}` does NOT re-parse \
         ({} parse error(s)).\n=== Formatted (pass 2) ===\n{second}",
        p2.errors.len(),
    );
}

/// Round-trip + idempotence guard for `gg fmt`, focused on the long binary-op
/// chain data-loss bug (chains long enough to trip the line-breaker were being
/// reflowed into a parser-INVALID `+`-continuation form, and a second fmt pass
/// then dropped the orphaned lines, losing code). Also covers a couple of other
/// chain shapes so the class can't silently reopen on a sibling operator.
#[test]
fn fmt_binary_chain_round_trips() {
    // The headline case: a long `+` chain that forces the line-breaker to wrap.
    // 100 terms is comfortably over the ~25-term break threshold and under the
    // parser's MAX_EXPR_DEPTH cap (which intentionally rejects ~129+ term
    // chains to avoid lowering-recursion overflow — a separate guard).
    let long_add = "a".to_string()
        + &" + a".repeat(99);
    let long_chain = format!(
        "void main():\n    String a = \"x\"\n    String s = {long_add}\n    print(s.len())\n"
    );
    assert_fmt_round_trips("long_add_chain", &long_chain);

    // A long boolean `and` chain (distinct operator, distinct precedence path).
    let mut bool_src = String::from("void main():\n");
    let names: Vec<String> = (0..40).map(|i| format!("flag_{i}")).collect();
    for n in &names {
        bool_src.push_str(&format!("    bool {n} = true\n"));
    }
    bool_src.push_str(&format!("    bool result = {}\n", names.join(" and ")));
    bool_src.push_str("    print(result)\n");
    assert_fmt_round_trips("long_and_chain", &bool_src);

    // A long arithmetic chain inside a `return` (chain as a statement tail).
    let ret_terms = "1".to_string() + &" + 1".repeat(59);
    let ret_src = format!(
        "int total():\n    return {ret_terms}\n\nvoid main():\n    print(total())\n"
    );
    assert_fmt_round_trips("long_return_chain", &ret_src);

    // A short chain that fits on one line: must NOT gain spurious parens and
    // must round-trip (the flat-mode path of the same code).
    let short_src =
        "void main():\n    int x = 1 + 2 + 3\n    print(x)\n";
    assert_fmt_round_trips("short_chain_flat", short_src);
    assert!(
        !gorget::formatter::format_source_infallible(short_src).contains("(1 + 2 + 3)"),
        "short binary chain that fits should NOT be parenthesized"
    );

    // Round XXXVIII Track C (gorget-js snag #15 Class 2): long `??` chain
    // on a NEW axis — `Expr::DefaultOp` was missed by R36's FMT-A sweep
    // and emitted `int r = a\n    ?? b` (bare leading `??` continuation),
    // which the lexer treats as NEWLINE + INDENT (no dot-carve-out for
    // `??`) so the parser rejects with `expected expression, found INDENT`
    // and a second `gg fmt` pass then drops the orphan line (data loss).
    // Fix routes `DefaultOp` through the shared
    // `wrap_multiline_expr_in_parens` helper so broken mode emits
    // `(a\n    ?? b)` (parseable). This corpus entry is the Class 2 axis
    // extension of the parse+idempotence guard.
    let long_default_op_src = format!(
        "int test(Option[int] a):\n    int r = a ?? {}\n    print(r)\n\nint main(): 0\n",
        // Long integer default expression forces the RHS past the line budget.
        (0..40).map(|i| format!("{i}")).collect::<Vec<_>>().join(" + "),
    );
    assert_fmt_round_trips("long_default_op", &long_default_op_src);

    // LEFT-nested `??` chain — parse+idempotence path (build+run of the
    // left-nested shape hits a distinct pre-existing runtime segfault
    // unrelated to formatting; parse-only coverage lives here).
    let long_default_op_left_nested_chain = format!(
        "int test(Option[int] a, Option[int] b):\n    int r = a ?? b ?? {}\n    print(r)\n\nint main(): 0\n",
        (0..40).map(|i| format!("{i}")).collect::<Vec<_>>().join(" + "),
    );
    assert_fmt_round_trips(
        "long_default_op_left_nested_chain",
        &long_default_op_left_nested_chain,
    );
}

/// Round XXXVI FMT-C: **semantic** fmt round-trip guard. For each
/// fixture in the curated list, build & run the ORIGINAL fixture and
/// capture stdout; then run `gg fmt` on a copy, build & run the
/// REFORMATTED fixture, and assert the stdout matches. This catches
/// silent-miscompile classes that the existing `fmt_binary_chain_round_trips`
/// (parse + idempotence only) does NOT catch — the R35 → R36 headline
/// defect was `(a + b) / 2` re-emitting as `a + b / 2` (both parse
/// cleanly, both are idempotent, but they compute different values).
///
/// This is the missing gate that would have caught R35's fmt sweep
/// BEFORE it broke bootstrap (Core #6 — the recurring bug class gets
/// an executable guard, not more prose). Fixtures added here become
/// exercisable regression pins for the FMT-A/FMT-B arm classes.
///
/// The curated list starts with the FMT-A POS fixtures; add more
/// fixtures as new operand classes surface (Core #4 sibling-drift).
#[test]
#[serial(gg_build)]
fn fmt_round_trip_semantic() {
    // Fixtures whose fmt round-trip must preserve stdout. Start with
    // the Round XXXVI FMT-A arm-class POS fixtures; extend as new
    // operand classes surface. Each entry: (fixture-basename, expected-stdout).
    // Expected stdout comes from running the ORIGINAL fixture pre-fmt.
    let corpus: &[(&str, &str)] = &[
        // FMT-A: format_binary_chain paren-drop.
        ("fmt_paren_binop_precedence.gg", "5"),
        // FMT-A: Expr::UnaryOp Neg paren-drop.
        ("fmt_paren_unary_neg.gg", "-7"),
        // FMT-A: Expr::UnaryOp Not paren-drop (distinct prefix_bp=20).
        ("fmt_paren_not_operand.gg", "true"),
        // FMT-A: postfix-receiver paren-drop (method call receiver).
        ("fmt_paren_postfix_receiver.gg", "11"),
        // FMT-A: Expr::As paren-drop (as-cast operand).
        ("fmt_paren_as_cast.gg", "-3"),
        // FMT-A: same-precedence right-nested LEFT-assoc binops.
        ("fmt_paren_binop_right_nested.gg", "3\n12\n0\n128"),
        // FMT-A: Pow (only RIGHT-assoc) LEFT-nest paren-drop.
        ("fmt_paren_pow_left_nest.gg", "64"),
        // FMT-A: IIFE closure — closure as postfix-receiver of a call.
        // Surfaced by the `scripts/fmt_sweep_smoke.sh` corpus sweep
        // (Round XXXVI FMT-C bring-up): `((int x): x * x)(5)` was
        // being re-emitted as `(int x): x * x(5)` which reparses with
        // `x * x(5)` as the closure body — the outer call is lost.
        // effective_outer_bp gives closures/if/match/do/block bp 0
        // so they always wrap in postfix/infix embedding.
        ("closure_iife.gg", "25\n10\nhello world"),
        // Round XXXVIII Track C: `Expr::DefaultOp` (`??`) long-RHS wrap
        // (gorget-js snag #15 Class 2). R36 missed this arm; before the
        // fix `gg fmt` emitted `a\n    ?? b` (unparseable). Fix routes
        // through `wrap_multiline_expr_in_parens`.
        ("fmt_long_default_op.gg", "42"),
        // gorget-js snag #15f: integer-literal RADIX preservation. The
        // VALUE must be identical after fmt whether a literal was written
        // hex/oct/bin/decimal (all lex to the same `IntLiteral`); the
        // companion `fmt_radix_preserved` test pins the TEXT (spelling
        // survives). This value-net catches a round-trip that changed a
        // literal's meaning.
        (
            "fmt_radix_preserved.gg",
            "92\n92\n92\n92\n43981\n43981\n65535\n65535\n1000000\n-16\n11\nfs=16\nif-ok\nmatch-ok",
        ),
        // Track H: control-char `\xHH` escapes (ESC/BS/DEL + `\u{1b}`) and
        // printable Unicode (é/😀) must all round-trip through fmt with the
        // exact same scalar/byte values.
        (
            "fmt_control_char_escape.gg",
            "27\n91\n48\n109\n8\n27\n127\n195\n169\n240\n159\n152\n128",
        ),
    ];

    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    for (fixture, expected_stdout) in corpus {
        assert_fmt_round_trip_semantic(&manifest_dir, fixture, expected_stdout);
    }
}

/// Helper for `fmt_round_trip_semantic`: build+run ORIGINAL fixture,
/// then fmt a copy, build+run the reformatted copy, assert stdouts match.
fn assert_fmt_round_trip_semantic(
    manifest_dir: &Path,
    fixture: &str,
    expected_stdout: &str,
) {
    let fixture_path = manifest_dir.join("tests/fixtures").join(fixture);
    assert!(
        fixture_path.exists(),
        "Fixture not found: {}",
        fixture_path.display(),
    );

    // Step 1: run ORIGINAL and capture stdout — positive control.
    let orig_stdout = build_and_run_capture_stdout(&fixture_path, fixture);
    assert_eq!(
        orig_stdout.trim(),
        expected_stdout.trim(),
        "Pre-fmt run of {fixture} produced unexpected stdout — the fixture's \
         expected_stdout in `fmt_round_trip_semantic` is out of date or the \
         fixture is broken.",
    );

    // Step 2: read the source, format it in-memory (avoids touching the
    // real fixture file), and write to a tempdir copy.
    let source = std::fs::read_to_string(&fixture_path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", fixture_path.display()));
    let reformatted = gorget::formatter::format_source_infallible(&source);

    let tmp = tempfile::TempDir::new().expect("tempdir");
    let reformatted_path = tmp.path().join(fixture);
    // A fixture named with a SUBDIRECTORY (`fmt_author_parens/costumes.gg`)
    // needs that directory to exist in the tempdir before the write.
    if let Some(parent) = reformatted_path.parent() {
        std::fs::create_dir_all(parent)
            .unwrap_or_else(|e| panic!("cannot create tempdir path for {fixture}: {e}"));
    }
    std::fs::write(&reformatted_path, &reformatted)
        .unwrap_or_else(|e| panic!("cannot write reformatted {fixture}: {e}"));

    // Step 3: build+run reformatted and compare stdout.
    let reformatted_label = format!("{fixture} (reformatted)");
    let reformatted_stdout =
        build_and_run_capture_stdout(&reformatted_path, &reformatted_label);
    assert_eq!(
        reformatted_stdout.trim(),
        expected_stdout.trim(),
        "SEMANTIC DRIFT — `gg fmt` changed the program's stdout for {fixture}.\n\
         === Original stdout ===\n{orig_stdout}\n\
         === Reformatted stdout ===\n{reformatted_stdout}\n\
         === Reformatted source ===\n{reformatted}",
    );
}

/// Build a fixture with `gg build` and run the resulting binary,
/// returning captured stdout. Used by `fmt_round_trip_semantic`.
fn build_and_run_capture_stdout(fixture_path: &Path, label: &str) -> String {
    let build = build_with_timeout(gg_command("build").arg(fixture_path), label);
    assert!(
        build.status.success(),
        "Build FAILED for {label}:\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&build.stdout),
        String::from_utf8_lossy(&build.stderr),
    );
    let stem = fixture_path.file_stem().unwrap().to_str().unwrap();
    let dir = fixture_path.parent().unwrap();
    let exe_path = dir.join(stem);
    let run = run_with_timeout(&mut Command::new(&exe_path), label);
    assert!(
        run.status.success(),
        "Binary exited with error for {label}: status={:?}\nstdout:\n{}\nstderr:\n{}",
        run.status.code(),
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr),
    );
    // Clean up build artefacts alongside the fixture. BOTH backends' generated
    // sources: `.c` for the LIR/C backend and `.ll` for `--backend=llvm`. The
    // `.ll` was missing, so every LLVM run of a round-trip corpus left one
    // beside each fixture it built — invisible in `git status` (they are
    // ignored) and therefore accumulating unnoticed in the fixture tree.
    let _ = std::fs::remove_file(dir.join(format!("{stem}.c")));
    let _ = std::fs::remove_file(dir.join(format!("{stem}.ll")));
    let _ = std::fs::remove_file(&exe_path);
    String::from_utf8_lossy(&run.stdout).to_string()
}

/// D29: `Expr::Propagate` must round-trip as a **postfix** `!` on the call
/// (not a prefix bang, not fused with `!=`). Without this pin a missing
/// formatter arm silently drops marks on `gg fmt` of marked corpus.
#[test]
fn fmt_propagate_round_trips() {
    let src = "\
int parse(String s) throws String:
    return 1

int f(String s) throws String:
    return parse(s)!

void main():
    print(f(\"x\")! catch (e): 0)
";
    assert_fmt_round_trips("propagate_postfix", src);
    let formatted = gorget::formatter::format_source_infallible(src);
    assert!(
        formatted.contains("parse(s)!"),
        "formatter must render Propagate as postfix `!` after the call.\nformatted:\n{formatted}"
    );
    assert!(
        !formatted.contains("!parse"),
        "Propagate must not format as a prefix bang.\nformatted:\n{formatted}"
    );
    // Comparison with spaces must not fuse: `f()! != b` stays spaced.
    let cmp = "\
int g() throws String:
    return 1
void main():
    bool ok = g()! != 0
    print(ok)
";
    assert_fmt_round_trips("propagate_ne_compare", cmp);
    let cmp_fmt = gorget::formatter::format_source_infallible(cmp);
    assert!(
        cmp_fmt.contains("!") && cmp_fmt.contains("!="),
        "postfix mark and `!=` must both survive fmt.\nformatted:\n{cmp_fmt}"
    );
}

// ══════════════════════════════════════════════════════════════════════
// The fmt-fixture BODY: marker lookups must not see the fixture's own header
// ══════════════════════════════════════════════════════════════════════

/// `formatted` with the fixture's own LEADING COMMENT BLOCK removed.
///
/// A fmt fixture explains itself in a header of `#` lines, and `gg fmt`
/// reproduces that header in its output. Every assertion that searches the
/// output for a marker is therefore shadowed by any header line that happens to
/// mention it, and the failure is silent in BOTH directions:
///
///   * a `find`-the-first-line lookup measures the HEADER line instead of the
///     cell — so the test is red for the wrong reason, and cannot go green when
///     the behaviour is fixed, because a comment line can never satisfy a
///     positional claim;
///   * a `contains` assertion is SATISFIED by the header — so it can never go
///     red, and reads as coverage while guarding nothing.
///
/// Both have happened here. The class was found at four instances (two
/// graduated fixtures, a known-gap repro, and `fmt_radix_preserved`, whose
/// `-0x10` needle its own header spells), and each was fixed by rewording the
/// header — an invariant-asserting comment with no enforcer, which is exactly
/// what this class keeps defeating.
///
/// Skipping the header retires it at the LOOKUP, which is the write site: no
/// needle list to maintain, nothing to keep in sync, and header wording is free
/// again. Only the CONTIGUOUS leading run of comment/blank lines is dropped, so
/// a fixture whose cells are themselves comments inside a body keeps every one
/// of them.
fn fmt_body(formatted: &str) -> &str {
    let mut offset = 0usize;
    for line in formatted.split_inclusive('\n') {
        let t = line.trim();
        if t.is_empty() || t.starts_with('#') {
            offset += line.len();
        } else {
            break;
        }
    }
    &formatted[offset..]
}

/// The first line of the fixture's BODY containing `needle` — the marker
/// lookup, header-immune. See [`fmt_body`].
fn fmt_body_line_with<'a>(formatted: &'a str, needle: &str) -> Option<&'a str> {
    fmt_body(formatted).lines().find(|l| l.contains(needle))
}

/// True iff the fixture's BODY contains `needle`. See [`fmt_body`].
fn fmt_body_contains(formatted: &str, needle: &str) -> bool {
    fmt_body(formatted).contains(needle)
}

/// gorget-js snag #15f: `gg fmt` must PRESERVE an integer literal's RADIX,
/// hex digit-case, and `_` grouping instead of rewriting every literal to
/// decimal (`0x5C` -> `92`, the reported bug). The lexer discards radix — all
/// four forms lex to one `IntLiteral` — so the formatter recovers the author's
/// spelling from the node's source SPAN (`int_literal_text` in
/// src/formatter/mod.rs), the same source+span mechanism it uses for comments.
///
/// This pins the TEXT-level claim (each spelling survives verbatim) plus
/// idempotence + clean re-parse; the companion `fmt_radix_preserved.gg` entry
/// in `fmt_round_trip_semantic` pins the RUNTIME VALUE (build+run stdout
/// unchanged). Axis: radix {0x,0o,0b,dec} x hex-case {upper,lower} x
/// underscores {with,without} x position {vardecl, if-cond, match-arm, broken
/// multi-line collection element, negative -0x10, f-string interp}.
///
/// RED-verify: reverting the `int_literal_text` fix reverts EVERY spelling
/// below to decimal (all `contains` checks fail); reverting ONLY the
/// `self.source.clone()` threading in `element_to_string_at` reverts JUST the
/// broken-collection element (`0x000B` -> `11`), isolating the empty-source
/// sub-formatter axis hole (edge case #1).
#[test]
fn fmt_radix_preserved() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture = manifest_dir.join("tests/fixtures/fmt_radix_preserved.gg");
    let source = std::fs::read_to_string(&fixture)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", fixture.display()));

    // Idempotence + clean re-parse. Also exercises that verbatim emission is a
    // fixpoint: the emitted `0x5C` re-lexes to the same value at a span that
    // slices back to `0x5C`. `format_source_infallible` panics on a parse
    // error, so this also asserts the reformatted source stays parseable —
    // and, for the f-string interp literal `{0x10}`, that formatting a
    // synthetic-span operand does NOT panic (edge case #2).
    assert_fmt_round_trips("radix_preserved", &source);

    let formatted = gorget::formatter::format_source_infallible(&source);

    // Every author spelling must survive verbatim across the full axis.
    for needle in [
        "0x5C",           // hex, vardecl RHS
        "0o134",          // octal
        "0b1011100",      // binary
        "0xABCD",         // hex, UPPER digits
        "0xabcd",         // hex, lower digits
        "0xFF_FF",        // hex WITH underscore grouping
        "0xFFFF",         // hex WITHOUT underscore
        "1_000_000",      // DECIMAL underscore grouping (also preserved)
        "-0x10",          // negative hex (unary `-` + hex operand)
        "0x000B",         // element of the BROKEN multi-line collection —
                          // the empty-source sub-formatter would revert this
                          // to `11` (edge case #1)
        "f\"fs={0x10}\"", // f-string interpolation (synthetic-span operand)
    ] {
        assert!(
            // BODY, not the whole output: this fixture's own header spells
            // `-0x10` while explaining the axis, so a whole-output `contains`
            // was satisfied by the prose and could never go red.
            fmt_body_contains(&formatted, needle),
            "gg fmt dropped integer-literal radix: `{needle}` is missing from \
             the formatted output (rewritten to decimal?).\n=== formatted ===\n{formatted}"
        );
    }

    // The collection literal must ACTUALLY break multi-line so the
    // sub-formatter (`element_to_string`) path is exercised on the BROKEN
    // side — otherwise the `0x000B` check would pass via the flat path and
    // never touch the empty-source axis hole (edge case #1).
    //
    // R41 T-FMT-D: broken lists are fill-PACKED now, so an element no longer
    // gets a line to itself. The check is therefore "the literal spans more
    // than one line, and the element that was pushed onto a continuation line
    // still carries its radix" — which is the property that was ever meant,
    // stated without assuming the one-element-per-line shape.
    let arr_line = fmt_body_line_with(&formatted, "Vector[int] arr")
        .expect("the arr vardecl is missing from the formatted output");
    let after_open = arr_line
        .split_once("= [")
        .expect("the arr vardecl has no literal")
        .1;
    assert!(
        !after_open.contains(']'),
        "expected the collection literal to break multi-line so the \
         sub-formatter path is exercised.\n=== formatted ===\n{formatted}"
    );
    let continuation = formatted
        .lines()
        .skip_while(|l| !l.contains("Vector[int] arr"))
        .nth(1)
        .expect("the literal has no continuation line");
    assert!(
        continuation.trim_start().starts_with("0x"),
        "the element pushed onto the continuation line must keep its radix \
         (the empty-source sub-formatter would revert it to decimal).\n\
         continuation: {continuation:?}\n=== formatted ===\n{formatted}"
    );
}

/// R40 Track D output-review (F1), FIXED in R41 T-FMT-A: `gg fmt` preserves a
/// COMMENT-ONLY file (a source with no items) byte-for-byte.
///
/// The corruption was: the first comment gained a spurious leading gap and,
/// with >=2 comments, the first two were GLUED (the line break dropped) —
/// `# a\n# b\n` -> `  # a# b`. Root cause was the SENTINEL return of
/// `Formatter::last_real_content_before`, which answered `0` both for "content
/// ends at byte 0" and for "there is no content at all". In a file with no
/// items, `format`'s EOF hook took the latter for the former, decided the
/// file's FIRST comment was a *trailing* comment on a node that had never been
/// emitted, and injected it with the inline trailing-comment gap into an empty
/// buffer. The fix makes the empty case a distinct TYPE (`Option<usize>`), so
/// the trailing hook cannot fire before any content exists.
///
/// Graduated out of `known_gaps/` — the fix landed, and the parking reason that
/// kept the FIXTURE behind did not survive measurement. It claimed that a
/// `main`-less file would make `gg run` exit 1 and register a runtime-parity
/// non-MATCH; measured, `gg run` exits 1 CLEANLY, and a clean non-zero oracle
/// exit is `RuntimeParityOutcome::RustRejected`, which the scan excludes from
/// its denominator. It cannot become a non-MATCH. Promoting it is parity-neutral
/// and buys real coverage: `fmt_idempotent` enumerates top-level fixtures, so
/// the file is now swept by the corpus-wide fmt gates as well as by this test.
#[test]
fn fmt_comment_only_file_preserved() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture = manifest_dir.join("tests/fixtures/fmt_comment_only_file_corruption.gg");
    let source = std::fs::read_to_string(&fixture)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", fixture.display()));

    let formatted = gorget::formatter::format_source_infallible(&source);

    // Intended: a comment-only file round-trips byte-identically (trailing-
    // newline policy aside).
    assert_eq!(
        formatted.trim_end_matches('\n'),
        source.trim_end_matches('\n'),
        "gg fmt corrupted a comment-only file.\n\
         === source ===\n{source}\n=== formatted ===\n{formatted}"
    );

    // Belt-and-suspenders on the two concrete symptoms, so a partial regression
    // still trips even if the equality check's whitespace policy ever loosens:
    // (1) no spurious leading indent on the first comment;
    assert!(
        !formatted.starts_with(' ') && !formatted.starts_with('\t'),
        "first comment gained a spurious indent.\n=== formatted ===\n{formatted}"
    );
    // (2) every authored comment stays on its OWN line (no glue).
    let src_comment_lines = source
        .lines()
        .filter(|l| l.trim_start().starts_with('#'))
        .count();
    let fmt_comment_lines = formatted
        .lines()
        .filter(|l| l.trim_start().starts_with('#'))
        .count();
    assert_eq!(
        fmt_comment_lines, src_comment_lines,
        "comment LINE count changed — comments were glued onto one line.\n\
         === formatted ===\n{formatted}"
    );
}

/// The LIVE VICTIM of the comment-only-file corruption (R41 S2 scout):
/// `tests/fixtures/self_host_lowerer/reachability.gg` is a real, in-tree,
/// comment-only module that `gg fmt` ATE one line per pass — the only
/// non-idempotence in the full-corpus sweep besides the minimal repro.
///
/// It needs its own wiring: `fmt_idempotent` enumerates TOP-LEVEL
/// `tests/fixtures/*.gg` only, so nothing under `self_host_lowerer/` gets
/// automatic coverage. Pins the stronger property — a FIXED POINT, i.e. the
/// file is already canonical, not merely stable after one pass.
///
/// RED pre-fix: pass 1 glued the first two comments and indented them
/// (`  # Reachability analysis module.#`), and each further pass consumed
/// another line.
#[test]
fn fmt_comment_only_live_victim_is_fixed_point() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let path = manifest_dir.join("tests/fixtures/self_host_lowerer/reachability.gg");
    let source = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    assert!(
        source.lines().all(|l| l.trim().is_empty() || l.trim_start().starts_with('#')),
        "canary premise: reachability.gg is no longer comment-only, so it no \
         longer exercises this class — re-derive the cell."
    );

    let first = gorget::formatter::format_source_infallible(&source);
    assert_eq!(
        first.trim_end_matches('\n'),
        source.trim_end_matches('\n'),
        "gg fmt is not a FIXED POINT on the comment-only self-host module.\n\
         === source ===\n{source}\n=== formatted ===\n{first}"
    );
    let second = gorget::formatter::format_source_infallible(&first);
    assert_eq!(first, second, "gg fmt is not idempotent on reachability.gg");
}

/// Round XXXVIII Track C (gorget-js snag #15 Class 2): `Expr::DefaultOp`
/// (`??`) with a long RHS was emitted by `gg fmt` as a bare leading-`??`
/// continuation that the parser rejects with `expected expression, found
/// INDENT`. Fix routes the arm through `wrap_multiline_expr_in_parens`
/// so broken mode emits `(a\n    ?? b)`.
///
/// This is the graduated live regression fixture for the committed
/// `tests/fixtures/fmt_long_default_op*.gg` files: format each one, then
/// `check` the formatted output must succeed. Extends the class beyond
/// what `fmt_binary_chain_round_trips` alone catches by pinning the
/// exact user-facing shape from the downstream report
/// (`env_get(...) ?? throw reference_error(...)`).
// Round XXXIX Track F (2026-08-09) — gorget-js snag #15b regression pin.
// Pre-R39: `gg fmt` wrapped single-expression `else:` / `catch` / `rethrow`
// arm bodies in a `do:` block, making the arm tail a READ position. Under
// R37 D27 (`!`→`^`), a bare `^x` tail in the original code parsed cleanly
// but the reformatted `else: do:\n    ^x` was rejected with
// `E_MoveInOperandPosition`. Fixed by extending `Expr::Block`'s inline
// carve-out at `src/formatter/mod.rs` to include single `Stmt::Expr` bodies
// (mirroring the existing Throw/Return carve-outs).
//
// Guard shape: (a) run_gg confirms the original source builds + runs
// (via the harness at the plain-fixture entry below); (b) this test formats
// the source in-process, asserts the `else: do:` wrap does NOT re-appear,
// and asserts the formatted output re-parses cleanly (the pre-fix RED
// signature was `E_MoveInOperandPosition` at parse time on the wrapped
// tail).
#[test]
fn fmt_else_catch_rethrow_no_do_wrap_on_move_tail() {
    use gorget::parser::Parser;

    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let path = manifest_dir.join("tests/fixtures/fmt_else_catch_rethrow_no_do_wrap.gg");
    let source = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let formatted = gorget::formatter::format_source_infallible(&source);

    // Positive control: no code line should emit a spurious `else: do:`
    // wrap on the move tail. Skip comment lines (`#`-prefix) — the fixture
    // header intentionally mentions the phrase to document the retired
    // defect. This checks the actual emitted code.
    let bad_code_line = formatted
        .lines()
        .find(|line| !line.trim_start().starts_with('#') && line.contains("else: do:"));
    assert!(
        bad_code_line.is_none(),
        "gorget-js snag #15b regression: `else: do:` wrap re-appeared on a code line.\n\
         Offending line: {:?}\n\
         === Formatted output ===\n{formatted}",
        bad_code_line
    );

    // Re-parse the formatted output — the pre-fix RED was a parse error
    // (`E_MoveInOperandPosition` on `^b` in operand position). If the
    // `do:` wrap re-appears on a move tail, this fires with the exact
    // pre-fix signature.
    let mut parser = Parser::new(&formatted);
    let _ = parser.parse_module();
    assert!(
        parser.errors.is_empty(),
        "gorget-js snag #15b regression: `gg fmt` output does not re-parse ({} error(s)).\n\
         === Formatted output ===\n{formatted}\n\
         === First parse error ===\n{:?}",
        parser.errors.len(),
        parser.errors.first(),
    );

    // Idempotence — a second pass must be byte-identical.
    let second = gorget::formatter::format_source_infallible(&formatted);
    assert_eq!(
        formatted, second,
        "Formatter NOT idempotent for fmt_else_catch_rethrow_no_do_wrap.gg.\n\
         === First pass ===\n{formatted}\n=== Second pass ===\n{second}",
    );
}

