// ─────────────────────────────────────────────────────────────────────
// GG_IMPL sub-req 2 gate: the self-host driver's standalone CLI surface.
//
// Drives the self-host `gg`-equivalent (driver.gg compiled to a binary) through
// its `build` / `run` / `check` / `--help` subcommands END-TO-END — the surface
// `GG_IMPL=selfhost` installs (scripts/gg_impl.sh). The pipeline was MANUAL-only
// before this; this is the first integration guard for it.
//
// Deterministic: runtime-dir + lib-dir are passed as ABSOLUTE repo paths (no
// $GG_RUNTIME_DIR / cwd drift), no network. Reuses the cached driver build.
//
// NOTE: this does NOT reuse `self_host_emit_cc_run` — that helper classifies any
// nonzero exit as `Crashed`, but the `run` case here ASSERTS a nonzero exit (the
// driver must PROPAGATE the program's exit code 7). We invoke the driver's
// build/run/check subcommands directly and assert on the exit code + stdout.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_cli_pipeline() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");

    let tmp_root = std::env::temp_dir().join(format!(
        "gg_impl_cli_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");

    // ── 1. `gg check <valid.gg>` → exits 0. ──────────────────────────────────
    let hello = manifest_dir.join("tests/fixtures/hello.gg");
    let check = run_with_timeout(
        Command::new(&driver_exe)
            .arg("check")
            .arg(&hello)
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "check hello.gg",
    );
    assert!(
        check.status.success(),
        "`gg check hello.gg` should exit 0 (clean program).\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&check.stdout),
        String::from_utf8_lossy(&check.stderr),
    );

    // ── 2. `gg --help` → exits 0 + prints a usage summary. ───────────────────
    let help = run_with_timeout(Command::new(&driver_exe).arg("--help"), "--help");
    assert!(help.status.success(), "`gg --help` should exit 0");
    let help_out = String::from_utf8_lossy(&help.stdout);
    assert!(
        help_out.contains("usage:")
            && help_out.contains("build")
            && help_out.contains("run")
            && help_out.contains("check"),
        "`gg --help` should print a usage summary listing the subcommands.\nstdout:\n{help_out}",
    );

    // ── 3. `gg build hello.gg -o out` → produces a binary that runs + exits 0.
    let out_bin = tmp_root.join("hello_cli");
    let build = run_with_timeout(
        Command::new(&driver_exe)
            .arg("build")
            .arg(&hello)
            .arg("-o")
            .arg(&out_bin)
            .arg(format!("--runtime-dir={}", runtime_dir.display()))
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "build hello.gg",
    );
    assert!(
        build.status.success(),
        "`gg build hello.gg -o out` should exit 0.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&build.stdout),
        String::from_utf8_lossy(&build.stderr),
    );
    assert!(out_bin.exists(), "`gg build` did not produce the output binary {out_bin:?}");
    let ran = run_with_timeout(&mut Command::new(&out_bin), "run built hello");
    assert!(
        ran.status.success(),
        "the built hello binary should exit 0; got {:?}",
        ran.status.code(),
    );
    assert_eq!(
        String::from_utf8_lossy(&ran.stdout).trim_end(),
        "Hello, World!",
        "the built hello binary should print the expected greeting",
    );

    // ── 4. `gg run <exit7>.gg` → PROPAGATES the program's exit code (7). ─────
    // The driver's `run` mode execs the compiled binary and `exit()`s its code,
    // so a non-zero program exit must surface as the driver's exit. (This is
    // why we can't reuse self_host_emit_cc_run: it would flag exit-7 as Crashed.)
    let exit7 = manifest_dir.join("tests/fixtures/gg_impl_exit7.gg");
    let run7 = run_with_timeout(
        Command::new(&driver_exe)
            .arg("run")
            .arg(&exit7)
            .arg(format!("--runtime-dir={}", runtime_dir.display()))
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "run gg_impl_exit7.gg",
    );
    assert_eq!(
        run7.status.code(),
        Some(7),
        "`gg run gg_impl_exit7.gg` should propagate exit code 7.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&run7.stdout),
        String::from_utf8_lossy(&run7.stderr),
    );

    // ── 5. `gg build --backend=llvm` → rejected cleanly (self-host emits C). ──
    let bad_backend = run_with_timeout(
        Command::new(&driver_exe)
            .arg("build")
            .arg(&hello)
            .arg("--backend=llvm")
            .arg(format!("--runtime-dir={}", runtime_dir.display()))
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "build --backend=llvm",
    );
    assert!(
        !bad_backend.status.success(),
        "`gg build --backend=llvm` should be rejected (the self-host emits C only)",
    );
    assert!(
        String::from_utf8_lossy(&bad_backend.stderr).contains("--backend"),
        "the --backend=llvm rejection should name the unsupported backend.\nstderr: {}",
        String::from_utf8_lossy(&bad_backend.stderr),
    );

    // ── 6. `gg run` with a BARE output name from a FOREIGN cwd. ──────────────
    // Regression for the filed defect: the driver execs the just-built binary
    // via system(), so a bare `-o hello_run` (no directory component) would be a
    // PATH lookup — and PATH excludes `.`, so the binary in the cwd was "not
    // found" (exit 127 / sh "not in a function"). The fix resolves the output to
    // an absolute path before exec. We run from `tmp_root` (a foreign cwd, NOT
    // where the .gg lives) with the runtime env UNSET (embedded runtime) and a
    // BARE `-o`, and assert the program actually runs + prints + exits 0.
    let run_cwd = tmp_root.join("run_cwd");
    std::fs::create_dir_all(&run_cwd).expect("failed to create run_cwd");
    // Import-free program: relocatable via the embedded runtime (Inc-2), so no
    // --runtime-dir / --lib-dir flags are needed and the output binary's dir is
    // purely the cwd — exactly the bare-name shape that triggered the bug.
    let run_src = run_cwd.join("greet.gg");
    std::fs::write(&run_src, "void main():\n    print(\"ran from foreign cwd\")\n")
        .expect("failed to write greet.gg");
    let run_bare = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&run_cwd)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("run")
            .arg("greet.gg")
            .arg("-o")
            .arg("greet_bin"),
        "run greet.gg -o greet_bin (bare name, foreign cwd)",
    );
    assert!(
        run_bare.status.success(),
        "`gg run greet.gg -o greet_bin` from a foreign cwd with a BARE output name \
         must resolve the binary to an absolute path before exec — a bare name is a \
         PATH lookup (PATH excludes `.`), so the just-built binary would be \
         \"not found\" (exit 127). Got {:?}.\nstdout: {}\nstderr: {}",
        run_bare.status.code(),
        String::from_utf8_lossy(&run_bare.stdout),
        String::from_utf8_lossy(&run_bare.stderr),
    );
    assert_eq!(
        String::from_utf8_lossy(&run_bare.stdout).trim_end(),
        "ran from foreign cwd",
        "`gg run` with a bare output name should actually execute the binary and \
         emit its stdout.\nstderr: {}",
        String::from_utf8_lossy(&run_bare.stderr),
    );

    // ── 7. `gg --version` / `-V` → exit 0 + prints `gg <version>` on stdout. ──
    // G1: mirror Rust gg's `println!("gg {}", CARGO_PKG_VERSION)` (src/main.rs).
    // The version literal tracks Cargo.toml `version` = "0.1.4-alpha".
    for vflag in ["--version", "-V"] {
        let ver = run_with_timeout(Command::new(&driver_exe).arg(vflag), vflag);
        assert!(
            ver.status.success(),
            "`gg {vflag}` should exit 0.\nstdout: {}\nstderr: {}",
            String::from_utf8_lossy(&ver.stdout),
            String::from_utf8_lossy(&ver.stderr),
        );
        assert!(
            String::from_utf8_lossy(&ver.stdout).contains("gg 0.1.4-alpha"),
            "`gg {vflag}` should print the version line `gg 0.1.4-alpha` (matching \
             Rust gg's `gg {{CARGO_PKG_VERSION}}`).\nstdout: {}",
            String::from_utf8_lossy(&ver.stdout),
        );
    }

    // ── 8. Unknown command → exit 1 + `Unknown command:` on stderr. ──────────
    // G2: an arg1 that is NOT a flag and does NOT end in `.gg` and is not one of
    // build/run/check is an unknown subcommand. Mirror Rust gg's
    // `Unknown command: <x>` prefix (src/main.rs), exit 1.
    let unknown = run_with_timeout(
        Command::new(&driver_exe).arg("frobnicate").arg(&hello),
        "frobnicate (unknown command)",
    );
    assert_eq!(
        unknown.status.code(),
        Some(1),
        "an unknown command should exit 1.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&unknown.stdout),
        String::from_utf8_lossy(&unknown.stderr),
    );
    assert!(
        String::from_utf8_lossy(&unknown.stderr).contains("Unknown command"),
        "an unknown command should print `Unknown command:` on stderr.\nstderr: {}",
        String::from_utf8_lossy(&unknown.stderr),
    );

    // ── 9. LEGACY harness shape preserved: arg1 = a real `.gg` PATH is NOT ────
    // treated as an unknown command. The G2 gate excludes `.gg`-suffixed args, so
    // `driver <file.gg> <lib_dir> --lir-c` (the shape self_host_bootstrap_fixed_point
    // / c_emit_comparison invoke) still flows through the legacy path. We assert the
    // legacy path emits C body to stdout and does NOT print the unknown-command
    // diagnostic. (self_host_bootstrap_fixed_point is the deeper canary.)
    let legacy = run_with_timeout(
        Command::new(&driver_exe)
            .arg(&hello)
            .arg(&lib_dir)
            .arg("--lir-c"),
        "legacy shape: driver hello.gg lib --lir-c",
    );
    assert!(
        legacy.status.success(),
        "the legacy harness shape `driver <file.gg> <lib_dir> --lir-c` must still \
         work (NOT be swallowed by the unknown-command gate).\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&legacy.stdout),
        String::from_utf8_lossy(&legacy.stderr),
    );
    assert!(
        !String::from_utf8_lossy(&legacy.stderr).contains("Unknown command"),
        "the legacy `.gg`-path shape must NOT be treated as an unknown command.\nstderr: {}",
        String::from_utf8_lossy(&legacy.stderr),
    );
    assert!(
        !String::from_utf8_lossy(&legacy.stdout).is_empty(),
        "the legacy `--lir-c` path should emit C body to stdout.\nstderr: {}",
        String::from_utf8_lossy(&legacy.stderr),
    );

    let _ = std::fs::remove_dir_all(&tmp_root);
}

/// Round XXV Track A (subsumed at scout stage 2026-08-02): SH driver's `gg run`
/// already propagates signal-death (exit 139 + signal-indicating stderr). The
/// XXIV Track B follow-up filing was a Core #12/#15d violation — source-read
/// diagnosis missed the `system()` → /bin/sh → shell-signal-translation chain.
///
/// This LIVE regression pin (previously `known_gaps/sh_gg_run_masks_signal_as_255.gg`)
/// asserts the SH driver behaviour: SH `driver run` on a SIGSEGV program exits
/// 139 with non-empty stderr containing signal indication ("Segmentation
/// fault" from /bin/sh; branded `SIGSEGV` from Rust would be nice-to-have but
/// requires a fork/execvp-based new runtime API — not filed unless asked).
///
/// ⚠⚠ ORACLE REPOINTED (R44 Track K). This test used to run
/// `known_gaps/sh_gg_run_propagates_signal_death.gg`, a nested-`Vector`
/// type-changing comprehension whose SIGSEGV was supplied by a self-host
/// COMPILER DEFECT — the list arm minting its accumulator from the SOURCE
/// element type. Track K fixed that, so the old oracle now exits 0 printing
/// `1`; its own fixture header predicted this red and said the answer is to
/// retire the oracle, never to weaken the assertion or "fix" the
/// comprehension back.
///
/// It now runs `tests/fixtures/stack_guard_deep_recursion.gg` — the same
/// oracle the RUST half (`gg_run_propagates_signal_death`) was repointed at
/// for the same reason: a BY-DESIGN depth-200000 non-tail recursion that
/// `tests/security.rs` (`sec_45_deep_recursion_stack_overflow`) ratifies as an
/// intentional stack overflow. An oracle that rides on a defect under repair
/// is not an oracle. The old fixture's PROGRAM is preserved as a live
/// regression cell at
/// `tests/fixtures/self_host_comprehension/graduated_nested_vector_source.gg`.
///
/// ⚠ RLIMIT_STACK is pinned to a stock 8MB, exactly as the Rust half pins it:
/// this program dies by SIGSEGV only at a stock stack limit, so an UNPINNED
/// invocation makes the oracle host-conditional (a huge host stack makes it
/// print 200000 and exit 0, which fails the assertion below with the actively
/// misleading `got Some(0)`). `;` and NOT `&&`: on a host whose HARD limit is
/// below 8MB the pin is a RAISE and fails, and with `&&` the shell would
/// short-circuit and `gg` would never run.
#[test]
#[serial(self_host_lowerer_driver)]
fn sh_gg_run_propagates_signal_death() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");
    let lib_dir = manifest_dir.join("stdlib");
    let fixture = manifest_dir.join("tests/fixtures/stack_guard_deep_recursion.gg");

    let output = run_with_timeout(
        Command::new("sh")
            .arg("-c")
            .arg("ulimit -S -s 8192; exec \"$0\" run \"$1\" \"$2\" \"$3\"")
            .arg(&driver_exe)
            .arg(&fixture)
            .arg(format!("--runtime-dir={}", runtime_dir.display()))
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "sh driver run stack_guard_deep_recursion.gg (pinned to 8MB)",
    );

    assert_eq!(
        output.status.code(),
        Some(139),
        "SH `driver run` on a SIGSEGV program must propagate 128+11=139, not mask it \
         — or the ulimit pin didn't take (host HARD stack limit below 8MB: look \
         for `ulimit: error setting limit` on stderr; a huge host stack makes \
         this program print 200000 and exit 0 instead).\
         \nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
    );
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        stderr.to_lowercase().contains("segmentation") || stderr.contains("SIGSEGV"),
        "SH `driver run` must emit signal-indicating stderr on signal death; got: {stderr:?}",
    );

    // Cleanup: remove build artifacts left next to the fixture.
    let dir = fixture.parent().unwrap();
    let stem = fixture.file_stem().unwrap().to_str().unwrap();
    let _ = std::fs::remove_file(dir.join(format!("{stem}.c")));
    let _ = std::fs::remove_file(dir.join(stem));
}

// ─────────────────────────────────────────────────────────────────────
// GG_IMPL Inc-2 gate: a built `gg-selfhost` is RELOCATABLE — it carries its
// runtime (the 62 `src/backend/c/runtime/*.c` files embedded into driver.gg via
// `embed_file`) so `build hello.gg -o hello && ./hello` works from ANY cwd with
// NO env vars. This is the whole point of Inc-2: drop the GG_RUNTIME_DIR /
// GG_LIB_DIR exports for a truly portable install.
//
// The driver binary built by `build_gg_dir_cached` IS the embedded gg-selfhost
// (the meta pass baked the 62 files in at build time). We run it from a tmpdir
// with the runtime/lib env UNSET and assert the build+run succeeds.
//
// Three checks, mirroring the 3-state precedence in read_runtime:
//   1. EMBEDDED (env unset, no flag) → build+run an import-free hello → exit 0.
//   2. ESCAPE HATCH `GG_RUNTIME_DIR=<real>` (env forces disk) → still works.
//   3. ESCAPE HATCH `--runtime-dir=<bogus>` (flag forces disk, OVERRIDES embed)
//      → FAILS to open the bogus runtime dir. This proves the flag genuinely
//      overrides the embed (the B1 no-op-flag defect the brief warned of), not
//      that it silently falls back to the baked-in copy.
//
// Import-free `hello` only: programs with `from std…` imports need Inc-3's
// `lib/std` embedding to be relocatable (the lib-dir is still resolved from
// disk / $GG_LIB_DIR here). `tests/fixtures/hello.gg` is import-free.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_relocatable_embedded_runtime() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");

    let tmp_root = std::env::temp_dir().join(format!(
        "gg_impl_reloc_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");

    // An import-free program (no `from std…`) — relocatable today (Inc-2).
    let hello = tmp_root.join("hello.gg");
    std::fs::write(&hello, "void main():\n    print(\"Hello, World!\")\n")
        .expect("failed to write hello.gg");
    let out_bin = tmp_root.join("hello");

    // ── 1. EMBEDDED: env UNSET, no --runtime-dir, cwd = the tmpdir. ──────────
    // The driver must read its runtime from the embedded table, not the cwd.
    let build = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("hello.gg")
            .arg("-o")
            .arg("hello"),
        "reloc build (embedded runtime, no env)",
    );
    assert!(
        build.status.success(),
        "RELOCATABLE build FAILED: `gg-selfhost build hello.gg` from a foreign cwd \
         with no GG_RUNTIME_DIR must use the EMBEDDED runtime and exit 0. If this \
         fails with `cannot open …runtime_preamble.c`, the embed table or the \
         read_runtime fallback regressed.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&build.stdout),
        String::from_utf8_lossy(&build.stderr),
    );
    assert!(out_bin.exists(), "relocatable build did not produce {out_bin:?}");
    let ran = run_with_timeout(&mut Command::new(&out_bin), "run relocatable hello");
    assert!(
        ran.status.success(),
        "the relocatably-built hello should exit 0; got {:?}",
        ran.status.code(),
    );
    assert_eq!(
        String::from_utf8_lossy(&ran.stdout).trim_end(),
        "Hello, World!",
        "the relocatably-built hello should print the greeting",
    );

    // ── 2. ESCAPE HATCH: GG_RUNTIME_DIR=<real> (env forces disk) → works. ────
    let out_env = tmp_root.join("hello_env");
    let build_env = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env("GG_RUNTIME_DIR", &runtime_dir)
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("hello.gg")
            .arg("-o")
            .arg("hello_env"),
        "reloc build (GG_RUNTIME_DIR escape hatch)",
    );
    assert!(
        build_env.status.success(),
        "GG_RUNTIME_DIR=<real> escape hatch should still build.\nstderr: {}",
        String::from_utf8_lossy(&build_env.stderr),
    );
    assert!(out_env.exists(), "GG_RUNTIME_DIR build did not produce {out_env:?}");
    let ran_env = run_with_timeout(&mut Command::new(&out_env), "run env-built hello");
    assert!(ran_env.status.success(), "env-built hello should exit 0");

    // ── 3. ESCAPE HATCH: --runtime-dir=<bogus> (flag forces disk, OVERRIDES
    //       the embed) → FAILS. Proves the flag is NOT a no-op (the B1 defect):
    //       a forced-disk read of a nonexistent dir must error, NOT silently
    //       fall back to the baked-in runtime.
    let bogus_dir = tmp_root.join("no_such_runtime");
    let build_bogus = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("hello.gg")
            .arg("-o")
            .arg("hello_bogus")
            .arg(format!("--runtime-dir={}", bogus_dir.display())),
        "reloc build (--runtime-dir=bogus forces disk)",
    );
    assert!(
        !build_bogus.status.success(),
        "`--runtime-dir=<bogus>` must FORCE a disk read and FAIL (proving the flag \
         overrides the embed, not a silent no-op fallback). It unexpectedly \
         succeeded.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&build_bogus.stdout),
        String::from_utf8_lossy(&build_bogus.stderr),
    );

    // ── 4. BYTE-IDENTITY: the embedded-path preamble == the disk-path preamble.
    //       Both `--emit-c` dumps must be byte-identical — confirms the UTF-8
    //       round-trip through escape_c_string is faithful for all embedded
    //       files (59/62 carry non-ASCII comment-header bytes).
    let emit_embedded = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("hello.gg")
            .arg("--emit-c"),
        "emit-c (embedded)",
    );
    assert!(emit_embedded.status.success(), "embedded --emit-c should succeed");
    let emit_disk = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("hello.gg")
            .arg("--emit-c")
            .arg(format!("--runtime-dir={}", runtime_dir.display())),
        "emit-c (disk)",
    );
    assert!(emit_disk.status.success(), "disk --emit-c should succeed");
    assert_eq!(
        emit_embedded.stdout, emit_disk.stdout,
        "the embedded-runtime emitted C must be BYTE-IDENTICAL to the disk-runtime \
         emitted C (the embed bytes are the same bytes read from disk). A mismatch \
         means escape_c_string mangled a byte on the embed round-trip.",
    );

    let _ = std::fs::remove_dir_all(&tmp_root);
}

// GG_IMPL Inc-3 gate: a built `gg-selfhost` is RELOCATABLE for programs WITH
// `from std…` imports — it carries the 28 `lib/std/*.gg` modules embedded into
// driver.gg via `embed_file` (the same mechanism as Inc-2's runtime), keyed on
// the normalized module path (`std.collections`, `std.math`), and consults that
// table in `load_imports` with the 3-state precedence: a LOCAL/lib-dir disk file
// always WINS (shadows the embed), an explicit `--lib-dir=`/`GG_LIB_DIR` forces
// DISK, and only when neither resolves does the embedded copy serve the std
// module (disk-miss-fallback for non-std namespaces).
//
// Five checks:
//   1. EMBEDDED (env unset, no flag, foreign cwd) → build+run a `from std.math
//      import PI` program → prints `3.141593`. PROVE-IT-BITES: the baseline
//      SILENTLY MISCOMPILES this to `0` (`unknown identifier 'PI'` →
//      OpConstI64(0)) — the silent-skip-on-import-miss the embed fixes.
//   2. ESCAPE HATCH `GG_LIB_DIR=<real>` (env forces disk) → still works (3.141593).
//   3. ESCAPE HATCH `--lib-dir=<bogus>` (flag forces disk, OVERRIDES the embed)
//      → the std module is NOT found on the bogus disk path and is NOT fetched
//      from the embed → the build does NOT produce a correct binary. Proves the
//      flag genuinely forces disk (NOT a silent no-op fallback to the baked-in
//      copy). (The self-host's load_imports silently skips a true import miss, so
//      the build still exits 0 but the program is the same `0` miscompile — we
//      assert the OUTPUT is NOT the correct value, which a no-op-flag-fallback
//      would have produced.)
//   4. LOCAL-MODULE SHADOWING: a local `std/math.gg` in the cwd (resolved via
//      base_dir in resolve_module_path) shadows the embedded copy → its value
//      wins. Proves local-disk beats embed.
//   5. BYTE-IDENTITY: the embedded-path emitted C == the `--lib-dir=<disk>`
//      emitted C (the embed bytes are the same bytes read from disk).
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_relocatable_embedded_libstd() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");

    let tmp_root = std::env::temp_dir().join(format!(
        "gg_impl_reloc_libstd_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");

    // A program that imports a std module (needs the embedded lib/std to be
    // relocatable). `from std.math import PI` → print(PI) → `3.141593`.
    let prog = tmp_root.join("pi.gg");
    std::fs::write(&prog, "from std.math import PI\n\nvoid main():\n    print(PI)\n")
        .expect("failed to write pi.gg");
    let expected = "3.141593";

    // ── 1. EMBEDDED: env UNSET, no --lib-dir, cwd = the tmpdir. ──────────────
    let out_bin = tmp_root.join("pi");
    let build = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("pi.gg")
            .arg("-o")
            .arg("pi"),
        "reloc libstd build (embedded, no env)",
    );
    assert!(
        build.status.success(),
        "RELOCATABLE std-import build FAILED: `gg-selfhost build pi.gg` from a foreign \
         cwd with no GG_LIB_DIR must resolve `from std.math import PI` from the EMBEDDED \
         lib/std table and exit 0.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&build.stdout),
        String::from_utf8_lossy(&build.stderr),
    );
    assert!(out_bin.exists(), "relocatable std-import build did not produce {out_bin:?}");
    let ran = run_with_timeout(&mut Command::new(&out_bin), "run relocatable pi");
    assert!(ran.status.success(), "the relocatably-built pi should exit 0");
    assert_eq!(
        String::from_utf8_lossy(&ran.stdout).trim_end(),
        expected,
        "the relocatably-built std-importing program must print PI from the embedded \
         lib/std/math.gg. If it prints `0`, the embed table or the load_imports \
         consultation regressed (the baseline silent miscompile).",
    );

    // ── 2. ESCAPE HATCH: GG_LIB_DIR=<real> (env forces disk) → works. ────────
    let out_env = tmp_root.join("pi_env");
    let build_env = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env("GG_LIB_DIR", &lib_dir)
            .arg("build")
            .arg("pi.gg")
            .arg("-o")
            .arg("pi_env"),
        "reloc libstd build (GG_LIB_DIR escape hatch)",
    );
    assert!(
        build_env.status.success(),
        "GG_LIB_DIR=<real> escape hatch should still build.\nstderr: {}",
        String::from_utf8_lossy(&build_env.stderr),
    );
    let ran_env = run_with_timeout(&mut Command::new(&out_env), "run env-built pi");
    assert!(ran_env.status.success(), "env-built pi should exit 0");
    assert_eq!(
        String::from_utf8_lossy(&ran_env.stdout).trim_end(),
        expected,
        "GG_LIB_DIR=<real> build should read PI from disk and print {expected}",
    );

    // ── 3. ESCAPE HATCH: --lib-dir=<bogus> (flag forces disk, OVERRIDES embed).
    //       The std module is NOT on the bogus path and is NOT fetched from the
    //       embed → the program is the `0` miscompile, NOT the correct value.
    //       Proves the flag forces disk (not a silent no-op fallback to embed).
    let bogus_dir = tmp_root.join("no_such_libdir");
    let out_bogus = tmp_root.join("pi_bogus");
    let build_bogus = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("pi.gg")
            .arg("-o")
            .arg("pi_bogus")
            .arg(format!("--lib-dir={}", bogus_dir.display())),
        "reloc libstd build (--lib-dir=bogus forces disk)",
    );
    // The self-host load_imports silently skips a true import miss, so the build
    // exits 0 but PI is unresolved → OpConstI64(0). The key assertion is the
    // OUTPUT is NOT the correct value: a no-op flag that silently fell back to the
    // embed would have produced `3.141593`. So `!= expected` proves the override.
    let bogus_out = if build_bogus.status.success() && out_bogus.exists() {
        let r = run_with_timeout(&mut Command::new(&out_bogus), "run bogus-libdir pi");
        String::from_utf8_lossy(&r.stdout).trim_end().to_string()
    } else {
        String::new()
    };
    assert_ne!(
        bogus_out, expected,
        "`--lib-dir=<bogus>` must FORCE a disk read and NOT silently fall back to the \
         embedded lib/std (the no-op-flag defect). It unexpectedly produced the correct \
         PI value, meaning the flag did not override the embed.",
    );

    // ── 4. LOCAL-MODULE SHADOWING: a local `std/math.gg` shadows the embed. ──
    let shadow_root = tmp_root.join("shadow");
    std::fs::create_dir_all(shadow_root.join("std")).expect("mkdir shadow/std");
    std::fs::write(shadow_root.join("std/math.gg"), "const float PI = 999.0\n")
        .expect("write shadow std/math.gg");
    std::fs::write(
        shadow_root.join("pi.gg"),
        "from std.math import PI\n\nvoid main():\n    print(PI)\n",
    )
    .expect("write shadow pi.gg");
    let out_shadow = shadow_root.join("pi_shadow");
    let build_shadow = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&shadow_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("pi.gg")
            .arg("-o")
            .arg("pi_shadow"),
        "reloc libstd build (local-module shadowing)",
    );
    assert!(
        build_shadow.status.success(),
        "local-module-shadowing build should succeed.\nstderr: {}",
        String::from_utf8_lossy(&build_shadow.stderr),
    );
    let ran_shadow = run_with_timeout(&mut Command::new(&out_shadow), "run shadowed pi");
    assert!(ran_shadow.status.success(), "shadowed pi should exit 0");
    assert_eq!(
        String::from_utf8_lossy(&ran_shadow.stdout).trim_end(),
        "999.000000",
        "a LOCAL `std/math.gg` (resolved via base_dir) must SHADOW the embedded \
         lib/std/math.gg — the local disk file wins. If this prints 3.141593, the embed \
         is incorrectly consulted before the local-disk resolution.",
    );

    // ── 5. BYTE-IDENTITY: embedded-path emitted C == --lib-dir=<disk> emitted C.
    let emit_embedded = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("pi.gg")
            .arg("--emit-c"),
        "emit-c (embedded libstd)",
    );
    assert!(emit_embedded.status.success(), "embedded --emit-c should succeed");
    let emit_disk = run_with_timeout(
        Command::new(&driver_exe)
            .current_dir(&tmp_root)
            .env_remove("GG_RUNTIME_DIR")
            .env_remove("GG_LIB_DIR")
            .arg("build")
            .arg("pi.gg")
            .arg("--emit-c")
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "emit-c (disk libstd)",
    );
    assert!(emit_disk.status.success(), "disk --emit-c should succeed");
    assert_eq!(
        emit_embedded.stdout, emit_disk.stdout,
        "the embedded-lib/std emitted C must be BYTE-IDENTICAL to the disk-lib/std \
         emitted C (the embed bytes are the same bytes read from disk). A mismatch means \
         the embed round-trip mangled a byte of a lib/std module.",
    );

    let _ = std::fs::remove_dir_all(&tmp_root);
}

// INTENDED-BEHAVIOR BREADCRUMB (per CLAUDE.md "Don't redesign around compiler
// gaps"): `gg check` on an ILL-TYPED program SHOULD exit NONZERO. It does not
// TODAY — the self-host typechecker is PERMISSIVE (most of Rust's `self.error`
// check sites are unmigrated; TODO.md "gg check PERMISSIVENESS" + "explicit-
// VarDecl path skips initializer inference" + "42 of 47 Rust self.error sites
// unmigrated"). The `check` CLI plumbing is correct (it surfaces whatever
// `has_errors` reports); the defect is in the typechecker, filed separately and
// NOT fixed by this CLI work. This test is wired to the INTENDED behavior so it
// FLIPS GREEN the moment the typechecker starts rejecting ill-typed programs —
// a live executable record of the gap, not a silent workaround.
#[test]
#[ignore = "self-host typechecker is permissive; flips green when the filed \
            typechecker diagnostic gap (TODO.md gg check PERMISSIVENESS) is closed"]
#[serial(self_host_lowerer_driver)]
fn self_host_check_rejects_illtyped() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");

    let tmp_root = std::env::temp_dir().join(format!(
        "gg_impl_check_bad_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");

    // An ill-typed program: an int binding initialized with a String literal.
    // Rust gg rejects this; the self-host typechecker currently accepts it.
    let bad = tmp_root.join("illtyped.gg");
    std::fs::write(&bad, "void main():\n    int x = \"s\"\n    print(x)\n")
        .expect("failed to write illtyped.gg");

    let check = run_with_timeout(
        Command::new(&driver_exe)
            .arg("check")
            .arg(&bad)
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "check illtyped.gg",
    );
    assert!(
        !check.status.success(),
        "`gg check` on an ill-typed program SHOULD exit nonzero (intended). \
         If this now fails, the typechecker-permissiveness gap is closed — \
         un-ignore this test and retire the interim note in driver.gg's check arm.\n\
         stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&check.stdout),
        String::from_utf8_lossy(&check.stderr),
    );

    let _ = std::fs::remove_dir_all(&tmp_root);
}

/// Self-host 2T get-chain materialize reject (Core #9 SH lane close).
///
/// Per-shape assertions matching the Rust/ggdef NEG set — not a single
/// "nonzero exit" pin (a partial under-reject after a resolver swap, e.g.
/// `.first()`/`.last()` stop descending, would still pass a weak gate).
/// Helpers: structural `lvalue_value_type` kind gate + `get_chain_root_*`,
/// wired into `reject_if_tainted_materialize_root` and `reject_amp_self_mutator`,
/// LOCAL place-or-get-chain gate in `reject_materialize_on_write`.
#[test]
#[serial(self_host_lowerer_driver)]
fn sh_cow_taint_getchain_reject() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let fixtures = manifest_dir.join("tests").join("fixtures");

    // NEG shapes — each must REJECT with the exact diagnostic code.
    // Uses the same fixtures as the Rust `check_gg_fails` suite so a
    // SH-only under-reject on one arm is visible immediately.
    let reject_shapes: &[(&str, &str)] = &[
        (
            "known_gaps/sh_cow_taint_getchain_reject.gg",
            "assign: h.items.get(0).unwrap().name = v",
        ),
        (
            "cow_taint_getchain_vector.gg",
            "assign (top-level twin): h.items.get(0).unwrap().name = v",
        ),
        (
            "cow_taint_getchain_firstlast.gg",
            "first/last: h.items.first().unwrap().name = v",
        ),
        (
            "cow_taint_getchain_compound.gg",
            "compound: h.items.get(0).unwrap().n += 1",
        ),
        (
            "cow_taint_getchain_receiver.gg",
            "mutating-builtin receiver: …unwrap().tags.push(5)",
        ),
        (
            "cow_taint_getchain_formation.gg",
            "&-formation: bump(&h.items.get(0).unwrap().n)",
        ),
    ];

    for (rel, shape) in reject_shapes {
        let fixture = fixtures.join(rel);
        let check = run_with_timeout(
            Command::new(&driver_exe)
                .arg("check")
                .arg(&fixture)
                .arg(format!("--lib-dir={}", lib_dir.display())),
            &format!("SH check {rel}"),
        );
        let stdout = String::from_utf8_lossy(&check.stdout);
        let stderr = String::from_utf8_lossy(&check.stderr);
        let combined = format!("{stdout}{stderr}");
        assert!(
            !check.status.success(),
            "self-host must REJECT get-chain 2T shape [{shape}] ({rel}) \
             with nonzero exit (matching Rust gg + ggdef).\nstdout: {stdout}\nstderr: {stderr}",
        );
        assert!(
            combined.contains("E_MoveWithoutOperator")
                || combined.contains("error[E_MoveWithoutOperator]"),
            "self-host must reject get-chain 2T shape [{shape}] ({rel}) with \
             E_MoveWithoutOperator (not some other error — a wrong diagnostic \
             or silent accept-then-later-fail is a regression).\nstdout: {stdout}\nstderr: {stderr}",
        );
    }

    // POS precision: USER `get` must stay ACCEPTED (reject ⊆ materialize).
    let user_get = fixtures.join("cow_taint_getchain_user_get_ok.gg");
    let pos = run_with_timeout(
        Command::new(&driver_exe)
            .arg("check")
            .arg(&user_get)
            .arg(format!("--lib-dir={}", lib_dir.display())),
        "SH check cow_taint_getchain_user_get_ok.gg",
    );
    assert!(
        pos.status.success(),
        "self-host must ACCEPT USER-get chain (reject ⊆ materialize) — \
         cow_taint_getchain_user_get_ok.gg.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&pos.stdout),
        String::from_utf8_lossy(&pos.stderr),
    );
}

// ─────────────────────────────────────────────────────────────────────
// Chain 2 gate: the self-host emits a FULL, standalone program.
//
// Proves `driver F lib --emit-c --runtime-dir=<abs runtime> | cc | run`
// produces the SAME stdout as `gg run F`, with NO external preamble splice.
// This is the deliverable that proves Chain 2 (self-host emits a complete
// compilable `.c` = runtime preamble + body) AND the regression net for it.
//
// Difference from `self_host_e2e`: that test splices the Rust runtime preamble
// in front of the self-host's body-only `--lir-c` output; this one uses
// `--emit-c`, where the self-host emits its OWN preamble (the conditionally-
// selected runtime `.c` files + emit_lir_helpers) from
// `lir_codegen.gg::emit_runtime_preamble`. No splice.
//
// Runs by DEFAULT (NOT GG_FULL-gated) so a regression fails an ordinary
// `cargo test --test integration` run. Cost is bounded by a SMALL curated set
// (~10 fixtures spanning ≥6 runtime families) reusing the cached driver build.
//
// The curated set is restricted to fixtures the self-host currently compiles
// CORRECTLY end-to-end. Fixtures that fail for a PRE-EXISTING self-host BODY
// miscompile (unrelated to the preamble — e.g. the `&global` scalar-read bug,
// or std-lib functions like `gorget_set_union` the body fails to lower) are
// EXCLUDED here and tracked as Chain 3 work, NOT worked around in the port
// (CLAUDE.md "don't redesign around compiler gaps"). The runtime preamble was
// verified correct for those fixtures (their families are emitted); only the
// body is wrong, which is out of Chain 2 scope.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_full_program() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");
    let gg_exe: PathBuf = gg_binary().to_path_buf();

    // Curated, deterministic, no-platform-lib asserted set. Every entry is a
    // confirmed end-to-end MATCH; together they span ≥6 distinct runtime
    // families. The third tuple element lists the runtime-module families each
    // fixture exercises and links against. STRING (RUNTIME_STRING +
    // RUNTIME_STRING_BASE_OPS) is emitted unconditionally but IS a distinct
    // runtime module the program links — every fixture is tagged STRING. The
    // other five (ARRAY/MAP/SET/STRING_ARRAY/TOSTR) are conditionally selected
    // by emit_runtime_preamble's family predicates. Together: ≥6 families.
    //
    // NOTE: the MATH family is now covered (R6 FIDELITY — see below). The
    // PARSE / SORT / STREXT / ERROR families still could not be covered by a
    // CLEAN fixture — every candidate hits a PRE-EXISTING self-host BODY
    // miscompile (GorgetArray sort-return type mismatch, etc.), NOT a preamble
    // bug. Their selection logic IS ported + faithful; the body-side gaps block
    // a clean runtime comparison. Logged below.
    //
    // R6 FIDELITY (de-excluded): static_init_imported / numeric_trait /
    //   math_constants now MATCH end-to-end and are asserted below. The three
    //   self-host gaps that blocked them are fixed:
    //     • `print(bool)` → `true`/`false` (was `1`/`0`) — lower.gg routes
    //       BOOL_TYPE through gorget_bool_to_str.
    //     • `float` arithmetic + print → correct value (was `0.000000`) —
    //       lower.gg binop result type follows the operand type (was hardcoded
    //       I64); lir_lower.gg OpConstF64 carries the true IEEE-754 bits via
    //       gorget_float_to_bits (was `v as int`, which truncated 1.5→1).
    //     • the `division by zero` in math_constants's floor() path is gone —
    //       float binops no longer take the integer IDiv guard.
    //
    // EXCLUDED (pre-existing self-host BODY miscompiles, NOT preamble bugs —
    // see TODO(chain3) below):
    //   dict_literal / closures / bare_tuples / enumerate / struct_nested_access
    //     — other pre-existing body codegen gaps (empty/garbled output).
    //   set_operations / stdlib_iter_join / vector_sort — body calls std-lib
    //     fns (gorget_set_union, VectorIter assigns) it fails to lower/type.
    //   datetime_format / json_edge_cases — body bugs / undefined gorget_str_*.
    // All reproduce under the `self_host_e2e` SPLICE path too, confirming they
    // are body-side, not preamble-side.
    let asserted: &[(&str, &str, &[&str])] = &[
        ("hello.gg", "basic arithmetic / control flow", &["STRING"]),
        ("control_nested_loops.gg", "nested loops", &["STRING"]),
        ("control_nested_match.gg", "nested match / enum dispatch", &["STRING"]),
        ("copy_struct_return.gg", "struct value return", &["STRING"]),
        ("enums.gg", "enum variants + match", &["STRING"]),
        ("string_methods.gg", "String base ops", &["STRING"]),
        ("vector_methods.gg", "Vector / array", &["STRING", "ARRAY", "STRING_ARRAY"]),
        ("collections_construct.gg", "collection construction", &["STRING", "ARRAY", "STRING_ARRAY"]),
        ("hashmap_string_keys.gg", "Dict / map", &["STRING", "ARRAY", "MAP", "STRING_ARRAY"]),
        ("hashset_methods.gg", "Set methods", &["STRING", "ARRAY", "MAP", "SET", "STRING_ARRAY"]),
        ("set_insert_contains.gg", "Set + to_str", &["STRING", "ARRAY", "MAP", "SET", "STRING_ARRAY", "TOSTR"]),
        ("fstring_basic.gg", "f-strings", &["STRING"]),
        // R6 FIDELITY: bool-print, float arithmetic/print, MATH constants.
        ("static_init_imported.gg", "bool-print + float static (INFINITY/NAN)", &["STRING", "TOSTR"]),
        ("numeric_trait.gg", "float arithmetic + f-strings + Numeric trait", &["STRING"]),
        ("math_constants.gg", "MATH (PI/E/TAU/sin/cos/floor) + float compares", &["STRING", "TOSTR", "MATH"]),
        // R7 FIDELITY: Task/async — `spawn` + RAII drop-join. Was the #1 CC-FAIL
        // (`Task__T` aliased to undeclared `TaskHandle`); now emits the inline
        // anon struct mirroring Rust c_lir/mod.rs:474, so it cc's and runs `ok`.
        ("spawn_drop_void.gg", "Task spawn + RAII drop-join", &["STRING", "TASK"]),
        // R8 FIDELITY: bool-predicate return-type inference. `r.is_some()` /
        // `oob.is_none()` in an f-string previously inferred I64 → printed
        // `1`/`0`; lower.gg's infer_method_return_type now maps is_some/is_none/
        // is_ok/is_error + the 8 char predicates to BOOL_TYPE, so both formatters
        // emit `gorget_bool_to_str` → `true`/`false` (mirrors Rust methods.rs:1129).
        ("bounds_check.gg", "Option is_some/is_none predicates in f-strings", &["STRING", "ARRAY"]),
        // R9 FIDELITY: `with <allocator>:`-block lowering. SWith was unhandled
        // in the self-host's lower_stmt → the whole block body was silently
        // DROPPED (printed only `done`). lower.gg now lowers SWith (mirror Rust
        // lower_with stmts/mod.rs:2732) — construct via `gorget_arena_new`
        // (POINTER-typed dst), push as the active allocator, run the body in a
        // block drop-scope, then pop + `gorget_arena_destroy`. Value-method-only
        // body (`pool.bytes_used()`); the void-extern-method allocator fixtures
        // (`pool.reset()`) await R10 (loader fn_sigs void-stub return types).
        ("set_arena.gg", "with-allocator block (Arena + Set + bytes_used)", &["STRING", "ARRAY", "MAP", "SET", "ALLOC"]),
    ];
    // TODO(chain3): dict_literal / closures / bare_tuples — pre-existing body
    //   codegen gaps (empty / garbled output), unrelated to the preamble.
    // TODO(chain3): RUNTIME_ERROR family is gate-untested here — the self-host
    //   lowers throw/catch to plain Result returns, and a test-mode fixture
    //   (the other RUNTIME_ERROR trigger) emits an atexit alloc-report line
    //   that needs `gg test` as oracle, not `gg run`. Cover when convenient.

    let tmp_root = std::env::temp_dir().join(format!(
        "gg_full_program_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");

    #[derive(Debug)]
    enum Outcome {
        Match,
        WrongOutput { first_diff: String },
        CcFailed { stderr_first: String },
        DriverFailed { stderr_first: String },
        Crashed { exit_code: Option<i32>, stderr_first: String },
        OracleFailed { stderr_first: String },
    }

    let mut results: Vec<(String, Outcome)> = Vec::new();
    let mut families_seen: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();

    for (fname, _desc, fams) in asserted {
        let fixture = manifest_dir.join("tests/fixtures").join(fname);
        let stem = fixture.file_stem().unwrap().to_string_lossy().to_string();
        let c_path = tmp_root.join(format!("{stem}_full.c"));
        let bin_path = tmp_root.join(format!("{stem}_full"));

        // Oracle: gg run F.
        let oracle = run_with_timeout(
            Command::new(&gg_exe).arg("run").arg(&fixture),
            fname,
        );
        if !oracle.status.success() {
            let stderr = String::from_utf8_lossy(&oracle.stderr);
            results.push((fname.to_string(), Outcome::OracleFailed {
                stderr_first: stderr.lines().next().unwrap_or("(no stderr)").to_string(),
            }));
            continue;
        }
        let oracle_stdout = String::from_utf8_lossy(&oracle.stdout).trim_end().to_string();

        // Self-host: driver F lib --emit-c --runtime-dir=<abs>.
        let emit = run_with_timeout(
            Command::new(&driver_exe)
                .arg(&fixture)
                .arg(&lib_dir)
                .arg("--emit-c")
                .arg(format!("--runtime-dir={}", runtime_dir.display())),
            fname,
        );
        if !emit.status.success() {
            let stderr = String::from_utf8_lossy(&emit.stderr);
            results.push((fname.to_string(), Outcome::DriverFailed {
                stderr_first: stderr.lines().next().unwrap_or("(no stderr)").to_string(),
            }));
            continue;
        }
        let full_c = String::from_utf8_lossy(&emit.stdout).to_string();
        if let Err(e) = std::fs::write(&c_path, &full_c) {
            results.push((fname.to_string(), Outcome::CcFailed {
                stderr_first: format!("write .c failed: {e}"),
            }));
            continue;
        }

        let cc_out = Command::new("cc")
            .arg("-O0").arg("-w")
            .arg("-o").arg(&bin_path)
            .arg(&c_path)
            .arg("-lm")
            .arg("-lpthread")
            .output();
        let cc_out = match cc_out {
            Ok(o) => o,
            Err(e) => {
                results.push((fname.to_string(), Outcome::CcFailed {
                    stderr_first: format!("spawn cc: {e}"),
                }));
                continue;
            }
        };
        if !cc_out.status.success() {
            let stderr = String::from_utf8_lossy(&cc_out.stderr);
            let first = stderr.lines()
                .find(|l| l.contains("error") || l.contains("undefined"))
                .or_else(|| stderr.lines().next())
                .unwrap_or("(no stderr)")
                .chars().take(200).collect::<String>();
            results.push((fname.to_string(), Outcome::CcFailed { stderr_first: first }));
            continue;
        }

        let run = run_with_timeout(&mut Command::new(&bin_path), fname);
        if !run.status.success() {
            let stderr = String::from_utf8_lossy(&run.stderr);
            results.push((fname.to_string(), Outcome::Crashed {
                exit_code: run.status.code(),
                stderr_first: stderr.lines().next().unwrap_or("(no stderr)").to_string(),
            }));
            continue;
        }
        let self_stdout = String::from_utf8_lossy(&run.stdout).trim_end().to_string();

        if self_stdout == oracle_stdout {
            for f in fams.iter() {
                families_seen.insert((*f).to_string());
            }
            results.push((fname.to_string(), Outcome::Match));
        } else {
            let first_diff = oracle_stdout
                .lines()
                .zip(self_stdout.lines())
                .enumerate()
                .find(|(_, (r, s))| r != s)
                .map(|(i, (r, s))| format!("L{i}: oracle={r:?} self={s:?}"))
                .unwrap_or_else(|| format!(
                    "line-count: oracle={} self={}",
                    oracle_stdout.lines().count(),
                    self_stdout.lines().count(),
                ));
            results.push((fname.to_string(), Outcome::WrongOutput { first_diff }));
        }
    }

    let _ = std::fs::remove_dir_all(&tmp_root);

    // Report (diagnostic-friendly, like the *_comparison tests).
    eprintln!("\n================================");
    eprintln!("Self-host Full-Program (--emit-c) Gate");
    eprintln!("================================");
    let mut matched = 0usize;
    let mut failures: Vec<String> = Vec::new();
    for (fname, outcome) in &results {
        match outcome {
            Outcome::Match => {
                matched += 1;
                eprintln!("  MATCH         {fname}");
            }
            Outcome::WrongOutput { first_diff } => {
                eprintln!("  WRONG-OUTPUT  {fname} | {first_diff}");
                failures.push(format!("{fname}: WRONG-OUTPUT ({first_diff})"));
            }
            Outcome::CcFailed { stderr_first } => {
                eprintln!("  CC-FAIL       {fname} | {stderr_first}");
                failures.push(format!("{fname}: CC-FAIL ({stderr_first})"));
            }
            Outcome::DriverFailed { stderr_first } => {
                eprintln!("  DRIVER-FAIL   {fname} | {stderr_first}");
                failures.push(format!("{fname}: DRIVER-FAIL ({stderr_first})"));
            }
            Outcome::Crashed { exit_code, stderr_first } => {
                eprintln!("  CRASH         {fname} | exit={exit_code:?} {stderr_first}");
                failures.push(format!("{fname}: CRASH (exit={exit_code:?} {stderr_first})"));
            }
            Outcome::OracleFailed { stderr_first } => {
                eprintln!("  ORACLE-FAIL   {fname} | {stderr_first}");
                failures.push(format!("{fname}: ORACLE-FAIL (gg run failed: {stderr_first})"));
            }
        }
    }
    eprintln!("\n  matched: {matched}/{}", results.len());
    eprintln!("  runtime families covered ({}): {:?}", families_seen.len(), families_seen);
    eprintln!("================================\n");

    // Regression net: every asserted fixture must MATCH, and the passing set
    // must span ≥6 distinct conditionally-selected runtime families.
    assert!(
        failures.is_empty(),
        "self_host_full_program: {} fixture(s) regressed:\n  {}",
        failures.len(),
        failures.join("\n  "),
    );
    assert!(
        !results.is_empty() && matched == results.len(),
        "self_host_full_program: asserted set must be non-empty and all-MATCH (matched {matched}/{})",
        results.len(),
    );
    assert!(
        families_seen.len() >= 6,
        "self_host_full_program: asserted set must span ≥6 runtime families, got {} ({:?})",
        families_seen.len(),
        families_seen,
    );
}

// ===========================================================================
// Chain 3 — splice-free runtime-parity harness
// ===========================================================================
//
// Per fixture: build via the self-host (`driver F lib --emit-c` → `cc` → run),
// compare STDOUT vs Rust `gg run` (the oracle). No preamble splice; OUTPUT is
// compared, never C-text. Two entry points share the machinery below:
//
//   * `self_host_runtime_diff`  — FLOORED DIAGNOSTIC, default-running (owner
//      2026-08-22); opt OUT with GG_RUNTIME_DIFF=0, which is what CI does.
//      NOT always-pass: it asserts a MATCH-count FLOOR and a non-MATCH-count
//      CEILING at the end of the fn (release + linux + default backend only —
//      see `parity_floor_active`). Full corpus, live `gg run` oracle. Prints
//      the honest parity number + the WRONG-OUTPUT / CC-FAIL backlog.
//      ⚠ The "env-gated, always-pass" description this comment used to carry
//      was stale from the opt-IN era and is exactly the false belief that let
//      the ceiling drift 148 -> 151 unobserved; do not restore it.
//   * `self_host_runtime`       — LOCK-IN NET, default-running, build-breaking.
//      Oracle = committed snapshots in tests/fixtures/runtime_snapshots/. For
//      each snapshotted fixture, re-emits via the self-host and asserts the run
//      output still matches the snapshot. Regression net for the passing set.
//
// The snapshot regen path lives in `self_host_runtime` under
// GG_REGEN_RUNTIME_SNAPSHOT=1; it materializes one `<stem>.out` per fixture
// that is a STABLE MATCH (self-host twice + oracle twice, identical).
//
// CLAUDE.md "don't redesign around compiler gaps": the exclusion set carries
// ONLY fixtures whose own stdout is not a stable cross-lane function of their
// source (the Rust output is itself unstable or host-specific). A fixture the
// self-host MISCOMPILES is NEVER excluded — it surfaces as WRONG-OUTPUT /
// CC-FAIL in the diagnostic and goes to the TODO backlog. Inflating parity by
// excluding self-host failures is the forbidden anti-pattern, and no
// `ParityExclusionKind` names it.
//
// ⛔ THE EXCLUSION IS DECLARED BY THE FIXTURE, NEVER INFERRED FROM ITS NAME.
// `fixture_parity_exclusion` reads a `#!parity-excluded <kind>: <evidence>`
// line out of the fixture's own leading comment block and is deliberately not
// given the stem, so a name CANNOT decide the question at any of the three
// consumers below (Core #2 / layering rule 2). Full rationale:
// `docs/devbook/27-comparison-bootstrap.md`.
//
// THE THREE CONSUMERS AND WHAT ADJUDICATES EACH. The classification is a
// judgement, so every consumer names the instrument that can overrule it —
// a consumer with no arbiter is a place where a wrong classification survives
// forever, and consumer 1 was exactly that until the ratchet below existed.
//
//   1. `self_host_runtime_diff` (the FLOORED DIAGNOSTIC) — calls the reader.
//      ARBITER: `attribute_parity_nondeterminism` + the
//      `EXPECTED_NONDETERMINISTIC` ratchet. A fixture wrongly treated as
//      DETERMINISTIC (under-declared) re-runs both lanes, is NAMED as a lane
//      disagreeing with itself, and FAILS the gate unless it is on the filed
//      list. ⚠ Nothing here catches the OTHER direction: a fixture wrongly
//      declared unstable is simply absent, and absence is invisible. That is
//      what the `untriaged` kind + `parity_untriaged_exclusions_shrink_only`
//      (`tests/lints.rs`) make countable instead of silent.
//   2. `regenerate_runtime_snapshots` (GG_REGEN_RUNTIME_SNAPSHOT=1) — calls the
//      reader. ARBITER: the run-twice stability filter, and it is FINAL here.
//      A fixture that survives the reader but varies across the double pass
//      gets no snapshot, so an under-declaration cannot reach the lock-in net
//      through this path.
//   3. `self_host_runtime` (the LOCK-IN NET, build-breaking) — NEVER calls the
//      reader. Its oracle is the committed `runtime_snapshots/*.out`, which
//      consumer 2 produces and wipes UNDER the classification, so the two can
//      drift apart silently between regens. ARBITER:
//      `parity_declared_fixtures_have_no_snapshot` (`tests/lints.rs`), which
//      fails if a declared-excluded fixture still has a snapshot (or a snapshot
//      has no fixture). ⚠ Declaring a fixture does NOT remove it from this net:
//      its `.out` is `git rm`'d in the same commit.

/// The declaration directive a fixture uses to take itself out of the
/// runtime-parity corpus. Lives in the fixture's LEADING comment block, in the
/// tree's established "`#!` fence inside leading `#` comments" convention (the
/// same one `#!spectest` uses — `spec/ggdef/src/frontmatter.rs`), so it is
/// invisible to the lexer and `gg run`/`gg build` are unaffected.
///
/// Shape, with the evidence free to run onto continuation lines so no line
/// blows the ratified 120-column budget (`fmt_no_new_over_budget_lines`):
///
/// ```text
/// #!parity-excluded untriaged: DEBT (todo/t0828) — no cause established.
/// #!  Excluded only because the retired filename heuristic matched
/// #!  `stem.starts_with("datetime_")`; its own header says "fully deterministic".
/// ```
///
/// A continuation is `#!` + WHITESPACE, which cannot collide with a fence
/// (`#!parity-excluded`, `#!spectest`, `#!end` are all `#!` + a word).
const PARITY_EXCLUDED_DECL: &str = "#!parity-excluded";

/// WHY a fixture's stdout is not a stable cross-lane function of its source.
///
/// TYPED, not a free string: `reason()` and `spelling()` are exhaustive
/// `match`es with NO `_` arm, so **rustc is the witness** that every kind the
/// reader can produce has both a wire spelling and a human reason. Adding a
/// variant without one does not compile.
///
/// ⛔ There is deliberately NO variant meaning "the self-host miscompiles it".
/// That fixture stays in the corpus as WRONG-OUTPUT / CC-FAIL and goes to the
/// TODO backlog — excluding it would be the forbidden parity-inflation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum ParityExclusionKind {
    /// The program reads the wall clock / current date into its own stdout.
    Clock,
    /// The program draws from an RNG.
    Random,
    /// The program binds/connects a socket or drives a peer stack.
    Network,
    /// A sleep, a timed wait, or a concurrent interleaving decides the output.
    Scheduling,
    /// The `bench` / `test` RUNNER prints elapsed wall-clock time into stdout —
    /// the program itself is deterministic, its harness output is not.
    Harness,
    /// The program reads runtime/allocator-internal state (`mem_live()`) into
    /// stdout, so the bytes differ per lane and per allocation history.
    Allocator,
    /// The output depends on the host environment beyond the program: an
    /// external binary, the host time zone, a device/windowing stack.
    Host,
    /// ⚠ DEBT — inherited from the retired filename-substring heuristic; NO
    /// cause has been established for this fixture. It is excluded only because
    /// of how it is SPELLED, which is exactly the defect this declaration
    /// retired. Each one is a candidate for reinstatement; see
    /// `parity_untriaged_exclusions_shrink_only` in `tests/lints.rs` for the
    /// shrink-only ratchet and `todo/` for the reinstatement work.
    Untriaged,
}

impl ParityExclusionKind {
    /// The wire spelling used in the fixture declaration. Exhaustive — rustc
    /// rejects a new variant that forgets its spelling.
    fn spelling(self) -> &'static str {
        match self {
            Self::Clock => "clock",
            Self::Random => "random",
            Self::Network => "network",
            Self::Scheduling => "scheduling",
            Self::Harness => "harness",
            Self::Allocator => "allocator",
            Self::Host => "host",
            Self::Untriaged => "untriaged",
        }
    }

    /// The reason text carried into the parity report. Exhaustive — rustc
    /// rejects a new variant that forgets its reason.
    fn reason(self) -> &'static str {
        match self {
            Self::Clock => "clock (the program reads the wall clock into stdout)",
            Self::Random => "random (the program draws from an RNG)",
            Self::Network => "network (binds/connects a socket or drives a peer stack)",
            Self::Scheduling => "scheduling (a sleep, timed wait or interleaving decides the output)",
            Self::Harness => "harness (the bench/test runner prints elapsed wall-clock time)",
            Self::Allocator => "allocator (reads mem_live()/runtime-internal state into stdout)",
            Self::Host => "host (depends on an external binary, the host time zone, or a device)",
            Self::Untriaged => "untriaged (DEBT — inherited from the retired filename heuristic)",
        }
    }

    /// Parse one wire spelling. An unrecognised kind is a LOUD error at the
    /// reader, never a silent "not declared" — a mis-parse would silently put a
    /// nondeterministic fixture back into a byte-compared corpus.
    fn parse(s: &str) -> Option<Self> {
        match s {
            "clock" => Some(Self::Clock),
            "random" => Some(Self::Random),
            "network" => Some(Self::Network),
            "scheduling" => Some(Self::Scheduling),
            "harness" => Some(Self::Harness),
            "allocator" => Some(Self::Allocator),
            "host" => Some(Self::Host),
            "untriaged" => Some(Self::Untriaged),
            _ => None,
        }
    }
}

/// One fixture's parity-exclusion declaration: the typed kind plus the
/// fixture-authored evidence sentence that justifies it.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ParityExclusion {
    kind: ParityExclusionKind,
    evidence: String,
}

impl ParityExclusion {
    /// The reason string the parity report prints for this fixture.
    fn reason(&self) -> String {
        format!("{} — {}", self.kind.reason(), self.evidence)
    }
}

/// Read a fixture's runtime-parity exclusion **from its SOURCE**.
///
/// ⛔ CORE #2 / LAYERING RULE 2 — this function is deliberately NOT given the
/// fixture's name. "Is this fixture's stdout a stable cross-lane function of
/// its source?" is a property of the PROGRAM, so the program declares it and
/// this accessor reads it. The predicate this replaced answered the question
/// with `stem.starts_with("httpserver_")` — which excluded `httpserver_router`
/// ("all core features exercised without TCP", per its own header) purely
/// because of how it is spelled, and left `test_process_timeout` in the corpus
/// for the same reason (`todo/t0820`). A name cannot decide meaning here even
/// by accident: there is no name in scope.
///
/// The declaration is only honoured inside the LEADING comment block — the
/// first non-comment, non-blank line ends the scan — matching `#!spectest`'s
/// "the block lives entirely in leading `#` comments" rule. A declaration
/// further down the file would be silently ignored, so
/// `parity_declarations_are_well_formed` (`tests/lints.rs`) fails on one.
///
/// Every malformed declaration is a LOUD `Err`, never a silent `None`: a
/// silent mis-parse would put a nondeterministic fixture back into a
/// byte-compared corpus, which is the exact failure class this reader exists
/// to make impossible.
fn fixture_parity_exclusion(src: &str) -> Result<Option<ParityExclusion>, String> {
    let mut found: Option<ParityExclusion> = None;
    let mut in_continuation = false;
    for line in src.lines() {
        let trimmed = line.trim_start();
        if trimmed.is_empty() {
            in_continuation = false;
            continue;
        }
        if !trimmed.starts_with('#') {
            break; // leading comment block is over
        }
        // `#!` + whitespace continues the evidence of the declaration above.
        if let Some(cont) = parity_continuation_text(trimmed) {
            if in_continuation {
                let decl = found.as_mut().expect("continuation implies a declaration");
                decl.evidence.push(' ');
                decl.evidence.push_str(cont);
                continue;
            }
            return Err(format!(
                "`#!` continuation line with no `{PARITY_EXCLUDED_DECL}` declaration \
                 directly above it: `{trimmed}`",
            ));
        }
        in_continuation = false;
        let Some(rest) = trimmed.strip_prefix(PARITY_EXCLUDED_DECL) else {
            continue;
        };
        let Some((kind_text, evidence)) = rest.split_once(':') else {
            return Err(format!(
                "malformed `{PARITY_EXCLUDED_DECL}` declaration: expected \
                 `{PARITY_EXCLUDED_DECL} <kind>: <evidence>`, got `{trimmed}`",
            ));
        };
        let kind_text = kind_text.trim();
        let Some(kind) = ParityExclusionKind::parse(kind_text) else {
            return Err(format!(
                "unknown parity-exclusion kind `{kind_text}` in `{trimmed}` — the kinds are \
                 clock / random / network / scheduling / harness / allocator / host / untriaged \
                 (`ParityExclusionKind` in tests/integration.rs). There is deliberately no kind \
                 for \"the self-host miscompiles it\": that fixture stays in the corpus.",
            ));
        };
        let evidence = evidence.trim().to_string();
        if evidence.is_empty() {
            return Err(format!(
                "`{PARITY_EXCLUDED_DECL} {kind_text}:` carries no evidence — every exclusion \
                 states WHAT varies, in the fixture, so the next reader can check it or \
                 reinstate the fixture.",
            ));
        }
        if found.is_some() {
            return Err(format!(
                "two `{PARITY_EXCLUDED_DECL}` declarations in one fixture — exactly one \
                 declaration decides (layering rule 3: one source of truth per axis).",
            ));
        }
        found = Some(ParityExclusion { kind, evidence });
        in_continuation = true;
    }
    Ok(found)
}

/// The text of a `#!`-continuation line, or `None` if the line is a fence
/// (`#!parity-excluded`, `#!spectest`, `#!end` — all `#!` + a word character)
/// or an ordinary `#` comment.
fn parity_continuation_text(trimmed_line: &str) -> Option<&str> {
    let rest = trimmed_line.strip_prefix("#!")?;
    if !rest.starts_with(|c: char| c.is_whitespace()) {
        return None;
    }
    Some(rest.trim())
}

/// `fixture_parity_exclusion` for a fixture on disk. A malformed declaration or
/// an unreadable fixture PANICS — the three consumers must never proceed on a
/// guessed classification.
fn fixture_parity_exclusion_at(path: &Path) -> Option<ParityExclusion> {
    let src = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("parity: cannot read fixture {}: {e}", path.display()));
    fixture_parity_exclusion(&src)
        .unwrap_or_else(|e| panic!("parity: {} — {e}", path.display()))
}

/// The reader, exercised on the shapes that must NOT silently succeed.
///
/// ⚠ The first case is the one that matters and the one this replaces: a
/// fixture whose NAME says one thing and whose DECLARATION says the other, with
/// the declaration winning. The retired predicate would have excluded
/// `httpserver_router` (its own header: "all core features exercised without
/// TCP") on its spelling alone, and would have missed a `datetime_`-shaped
/// fixture spelled `foo`. The reader cannot do either — it is never given a
/// name.
#[test]
fn parity_declaration_reader_ignores_the_name_and_rejects_malformed() {
    // 1. A name that SCREAMS "exclude me" decides nothing: no declaration, no
    //    exclusion. (`httpserver_`, `datetime_`, `stress_` were all families in
    //    the retired cascade.)
    for looks_excluded in ["httpserver_router", "datetime_basic", "stress_alloc_vectors"] {
        let src = format!("# Test: {looks_excluded} — no TCP, no clock.\nvoid main():\n    print(1)\n");
        assert_eq!(
            fixture_parity_exclusion(&src),
            Ok(None),
            "a fixture named like {looks_excluded} must not be excluded by its NAME",
        );
    }

    // 2. A name that says nothing, declaring: the DECLARATION decides.
    let declared = "#!parity-excluded clock: reads std.time time() into stdout\nvoid main():\n    print(1)\n";
    let got = fixture_parity_exclusion(declared).expect("well-formed").expect("declared");
    assert_eq!(got.kind, ParityExclusionKind::Clock);
    assert_eq!(got.evidence, "reads std.time time() into stdout");
    assert!(got.reason().starts_with("clock ("), "reason renders the typed kind: {}", got.reason());

    // 3. Every kind round-trips through its own wire spelling.
    for kind in [
        ParityExclusionKind::Clock,
        ParityExclusionKind::Random,
        ParityExclusionKind::Network,
        ParityExclusionKind::Scheduling,
        ParityExclusionKind::Harness,
        ParityExclusionKind::Allocator,
        ParityExclusionKind::Host,
        ParityExclusionKind::Untriaged,
    ] {
        assert_eq!(
            ParityExclusionKind::parse(kind.spelling()),
            Some(kind),
            "{kind:?} does not round-trip through `{}`",
            kind.spelling(),
        );
    }

    // 4. Malformed is LOUD, never a silent `None` — a silent mis-parse would
    //    put a nondeterministic fixture back into a byte-compared corpus.
    for bad in [
        "#!parity-excluded clock reads a clock\nvoid main():\n",          // no colon
        "#!parity-excluded wallclock: reads a clock\nvoid main():\n",     // unknown kind
        "#!parity-excluded clock:   \nvoid main():\n",                    // no evidence
        "#!parity-excluded clock: a\n#!parity-excluded host: b\nvoid main():\n", // two decls
    ] {
        assert!(
            fixture_parity_exclusion(bad).is_err(),
            "reader accepted a malformed declaration: {bad:?}",
        );
    }

    // 5. A declaration BELOW the leading comment block is not honoured — which
    //    is why `parity_declarations_are_well_formed` (tests/lints.rs) fails on
    //    one rather than letting it pass as "not declared".
    let below = "void main():\n    print(1)\n#!parity-excluded clock: too late\n";
    assert_eq!(fixture_parity_exclusion(below), Ok(None));

    // 6. `#!` + WHITESPACE continues the evidence (so no line has to blow the
    //    120-column budget); `#!` + a word is a FENCE and never a continuation.
    let wrapped = "#!parity-excluded network: binds a real TCP socket;\n\
                   #!  the port and the peer's timing decide the output\n\
                   # An ordinary comment, NOT part of the evidence.\n\
                   void main():\n";
    let got = fixture_parity_exclusion(wrapped).expect("well-formed").expect("declared");
    assert_eq!(
        got.evidence,
        "binds a real TCP socket; the port and the peer's timing decide the output",
    );
    assert_eq!(parity_continuation_text("#!spectest"), None, "a fence is not a continuation");
    assert_eq!(parity_continuation_text("#!end"), None, "a fence is not a continuation");
    assert_eq!(parity_continuation_text("#!  more"), Some("more"));

    // 7. A continuation with nothing to continue is LOUD, not silently dropped.
    let orphan = "# a header\n#!  orphaned continuation\nvoid main():\n";
    assert!(fixture_parity_exclusion(orphan).is_err());
}

/// The REAL reader over the REAL corpus, in the fast lane.
///
/// `parity_declarations_are_well_formed` (`tests/lints.rs`) re-implements the
/// grammar as a second opinion; this runs the actual `fixture_parity_exclusion`
/// the three consumers call, over every top-level fixture, so a reader change
/// that stops seeing the committed declarations is caught in 0.1s instead of at
/// the end of a ~12-minute release gate.
#[test]
fn parity_declarations_read_back_from_the_real_corpus() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixtures = runtime_parity_corpus(&manifest_dir);
    assert!(fixtures.len() > 2000, "corpus scan found only {} fixtures", fixtures.len());

    let mut by_kind: Vec<(ParityExclusionKind, usize)> = Vec::new();
    let mut thin: Vec<String> = Vec::new();
    let mut declared = 0usize;
    for f in &fixtures {
        // `_at` PANICS on a malformed declaration, which is the point: every
        // committed fixture must read back cleanly through the real path.
        let Some(decl) = fixture_parity_exclusion_at(f) else { continue };
        declared += 1;
        if decl.evidence.chars().count() < 20 {
            thin.push(format!(
                "{}: evidence is {} chars — say WHAT varies",
                f.file_stem().unwrap().to_string_lossy(),
                decl.evidence.chars().count(),
            ));
        }
        match by_kind.iter_mut().find(|(k, _)| *k == decl.kind) {
            Some((_, n)) => *n += 1,
            None => by_kind.push((decl.kind, 1)),
        }
    }
    by_kind.sort();
    eprintln!("parity declarations read back: {declared} / {} fixtures", fixtures.len());
    for (kind, n) in &by_kind {
        eprintln!("  {:<12}: {n}", kind.spelling());
    }
    assert!(thin.is_empty(), "declarations with no usable evidence:\n  {}", thin.join("\n  "));
    assert!(
        declared > 0,
        "the reader sees NO declarations in the corpus — every clock, RNG and socket fixture \
         would be byte-compared across lanes. The directive was renamed, the leading-block scan \
         broke, or the declarations were lost."
    );
}

/// Outcome of one fixture under the runtime-parity diagnostic.
#[derive(Debug, Clone)]
enum RuntimeParityOutcome {
    /// Both compilers agree. `agreed` is that shared (trimmed) stdout — retained
    /// so the ggdef adjudication post-pass (Track G2) can diff the definitional
    /// interpreter's output against it WITHOUT re-running the oracle.
    Match { agreed: String },
    WrongOutput { first_diff: String },
    CcFailed { detail: String },
    DriverFailed { detail: String },
    Crashed { exit_code: Option<i32>, stderr_first: String },
    /// Excluded by the fixture's own `#!parity-excluded` declaration. Carries
    /// the typed kind and the rendered reason (kind + fixture evidence).
    Excluded(ParityExclusionKind, String),
    /// Rust `gg run` rejected the fixture with a diagnostic (clean non-zero
    /// exit). An error-test fixture — excluded from parity.
    RustRejected,
    /// Rust `gg run` crashed (signal-terminated). Logged separately.
    RustCrash,
}

/// A MATCH whose agreed (both-compiler) output the definitional interpreter
/// (ggdef) contradicts — the rbw class (Track G2). `agreed` is what BOTH
/// compilers printed; `ggdef` is what the definition printed.
#[derive(Debug, Clone)]
struct BothWrong {
    stem: String,
    agreed: String,
    ggdef: String,
}

/// Adjudicate the MATCH set against ggdef, the definitional interpreter (Track
/// G2). Returns `(adj_match, unadj_match, both_wrong)`:
///   * `adj_match`   — stems where ggdef reached a `Value` AND its stdout equals
///     the agreed (both-compiler) output. The MATCH is confirmed by a third,
///     normative opinion.
///   * `unadj_match` — `(stem, reason)` where ggdef could NOT weigh in: outside
///     its phase-0 subset (FrontendError), a non-`Value` outcome
///     (trap/illformed/fuel), a float-render HOLD (D8 — a known ggdef gap, NOT a
///     both-wrong), an ICE (caught panic), or the native-stack exclude.
///   * `both_wrong`  — ggdef reached a `Value` that DISAGREES with the agreed
///     output. Each is a red-alert defect.
///
/// The verdict is TYPED on ggdef's `Outcome` enum (Core #2), never string-
/// matched. Runs SERIALLY in one 2 GiB-stack thread: ggdef's big-step evaluator
/// recurses on the native stack (fuel bounds the STEP count, not eval depth), so
/// it needs a large native stack — the setup `converter_agreement.rs` validated.
/// Serial is fine: ggdef is ~1ms/fixture, so the whole MATCH set adds ~1-2s.
fn adjudicate_matches(
    matched: &[String],
    agreed_by_stem: &std::collections::HashMap<String, String>,
    fixtures_dir: &Path,
) -> (Vec<String>, Vec<(String, String)>, Vec<BothWrong>) {
    let matched = matched.to_vec();
    let agreed = agreed_by_stem.clone();
    let fixtures_dir = fixtures_dir.to_path_buf();
    std::thread::Builder::new()
        .stack_size(2 * 1024 * 1024 * 1024)
        .name("ggdef-adjudicate".to_string())
        .spawn(move || {
            // Silence the panic hook for the duration: a ggdef ICE (a panic, not a
            // clean `Outcome`) on one fixture is caught below and recorded as
            // UNADJ; without this the report would be buried under its backtrace.
            with_silent_panic_hook(|| adjudicate_matches_body(&matched, &agreed, &fixtures_dir))
        })
        .expect("failed to spawn ggdef-adjudicate thread")
        .join()
        .expect("ggdef-adjudicate thread panicked")
}

fn adjudicate_matches_body(
    matched: &[String],
    agreed_by_stem: &std::collections::HashMap<String, String>,
    fixtures_dir: &Path,
) -> (Vec<String>, Vec<(String, String)>, Vec<BothWrong>) {
    let mut adj: Vec<String> = Vec::new();
    let mut unadj: Vec<(String, String)> = Vec::new();
    let mut both_wrong: Vec<BothWrong> = Vec::new();

    for stem in matched {
        // The designed unbounded-recursion fixture blows ggdef's native stack
        // even at 2 GiB (a filed native-recursion finding) — CLASSIFY_EXCLUDE.
        if ggdef::CLASSIFY_EXCLUDE.contains(&format!("{stem}.gg").as_str()) {
            unadj.push((stem.clone(), "ggdef-excluded (native-stack)".to_string()));
            continue;
        }
        let src = match std::fs::read_to_string(fixtures_dir.join(format!("{stem}.gg"))) {
            Ok(s) => s,
            Err(_) => {
                unadj.push((stem.clone(), "source-read-failed".to_string()));
                continue;
            }
        };
        let agreed_out = agreed_by_stem.get(stem).cloned().unwrap_or_default();

        // catch_unwind: a ggdef ICE (internal panic) on one fixture must not abort
        // the whole adjudication — record it UNADJ and move on. `run_source` only
        // reads the source and builds owned values, so `AssertUnwindSafe` is sound.
        let run = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            ggdef::run_source(&src, ggdef::CLASSIFY_FUEL)
        }));
        let run = match run {
            Ok(Ok(r)) => r,
            // Parse OR elaborate error ⇒ outside ggdef's definitional surface.
            Ok(Err(_)) => {
                unadj.push((stem.clone(), "ggdef-frontend-error (out of subset)".to_string()));
                continue;
            }
            Err(_) => {
                unadj.push((stem.clone(), "ggdef-panic (ICE)".to_string()));
                continue;
            }
        };

        match &run.outcome {
            ggdef::Outcome::Value(_) => {
                if run.stdout.trim_end() == agreed_out.trim_end() {
                    adj.push(stem.clone());
                } else if ggdef::classify::has_decimal_number(&agreed_out)
                    || ggdef::classify::has_decimal_number(&run.stdout)
                {
                    // D8 float-render HOLD: ggdef's decimal formatting differs from
                    // the backends' — a KNOWN ggdef gap, not a both-wrong. Mirrors
                    // classify.rs's `Float` route. (Crude: could mask a real
                    // both-wrong whose diff lines also carry decimals — noted in the
                    // scout report as the heuristic's limitation.)
                    unadj.push((stem.clone(), "float-render HOLD (D8)".to_string()));
                } else {
                    both_wrong.push(BothWrong {
                        stem: stem.clone(),
                        agreed: agreed_out.clone(),
                        ggdef: run.stdout.clone(),
                    });
                }
            }
            ggdef::Outcome::Trap(_) => unadj.push((stem.clone(), "ggdef-trap (101)".to_string())),
            ggdef::Outcome::IllFormed(_) => {
                unadj.push((stem.clone(), "ggdef-illformed (static reject)".to_string()))
            }
            ggdef::Outcome::FuelExhausted => {
                unadj.push((stem.clone(), "ggdef-fuel-exhausted".to_string()))
            }
        }
    }

    (adj, unadj, both_wrong)
}

/// Where `self_host_emit_cc_run` puts the self-host-compiled binary for one
/// fixture. ONE source of truth for the naming convention: the runtime-parity
/// mismatch attribution below re-runs that binary, and a second hand-written
/// `format!("{stem}_{tag}")` next to it would be a convention kept in sync by
/// hand (the exact shape the layering chapter's rule 3 forbids).
fn self_host_bin_path(tmp_root: &Path, stem: &str, tag: &str) -> PathBuf {
    tmp_root.join(format!("{stem}_{tag}"))
}

/// How many extra times the self-host binary is re-run when attributing a
/// runtime-parity mismatch, and how many extra times the Rust oracle is.
///
/// The self-host side is nearly free (the binary is already sitting in
/// `tmp_root`); the oracle side costs a `gg run` compile each, so it gets
/// fewer. POWER, since "re-run it a few times" is exactly the instrument that
/// CANNOT see a rare flapper in general: this re-run is CONDITIONAL ON A
/// MISMATCH HAVING JUST HAPPENED, which means the lane that flipped is sitting
/// in its MINORITY state. Measured on `shared_with_check_then_act` before it
/// was pinned (one pinned release binary, 8-way parallel load): the Rust lane
/// produced its minority output 27/400 and the self-host lane 11/400, so
/// conditional on a flip, P(a re-run reproduces the MAJORITY output and the
/// disagreement is seen) is 1 - 0.0675^2 ≈ 0.995 on the oracle side and
/// 1 - 0.0275^6 ≈ 1 - 4e-10 on the self-host side. An UNCONDITIONAL sweep at
/// the same K would have detected that fixture ~15% of the time and certified
/// it stable — which is why this instrument lives on the mismatch path and
/// nowhere else.
const PARITY_ATTRIBUTION_SELF_RERUNS: usize = 6;
const PARITY_ATTRIBUTION_ORACLE_RERUNS: usize = 2;

/// Attribute a runtime-parity mismatch: is this row parity DEBT, or is one of
/// the two lanes simply disagreeing WITH ITSELF?
///
/// A byte-exact differential gate is only meaningful over an output both lanes
/// pin. A fixture whose stdout is a function of the SCHEDULER rather than of
/// the program (`docs/language-design.md:94-95` — stale-condition warnings are
/// a design target and the scheduler is a pluggable knob, so interleaving is
/// admitted nondeterminism) will mismatch some fraction of sweeps and match the
/// rest, and the row then reads as a self-host parity defect that no amount of
/// reading the diff will explain. That misreading cost a full round-close
/// triage three gate runs before this attribution existed.
///
/// This EXCUSES NOTHING. The row stays in the WRONG-OUTPUT tally, both bounds
/// see exactly the counts they saw before, and no allowlist is involved — the
/// only thing that changes is that the printed line NAMES the nondeterminism
/// instead of leaving it to be rediscovered. The fix for a row this flags is
/// to pin the fixture's interleaving (`directive scheduler=…`, as the
/// `shared_stale_*` family does) or, if the nondeterminism is inherent, to add
/// a `#!parity-excluded <kind>: <evidence>` line to the FIXTURE — never to
/// leave it flapping.
///
/// Returns `None` when both lanes reproduced their own output every time (the
/// mismatch is real parity debt), or `Some(note)` naming the unstable lane.
fn attribute_parity_nondeterminism(
    gg_exe: &Path,
    fixture: &Path,
    self_bin: &Path,
    stem: &str,
    oracle_stdout: &str,
    self_stdout: &str,
) -> Option<String> {
    let mut self_variants: Vec<String> = vec![self_stdout.to_string()];
    for _ in 0..PARITY_ATTRIBUTION_SELF_RERUNS {
        let mut cmd = Command::new(self_bin);
        cmd.stdin(Stdio::null());
        let Ok(out) = run_with_timeout_catching(&mut cmd, stem) else { break };
        if !out.status.success() {
            break;
        }
        let s = String::from_utf8_lossy(&out.stdout).trim_end().to_string();
        if !self_variants.contains(&s) {
            self_variants.push(s);
        }
    }
    if self_variants.len() > 1 {
        return Some(format!(
            "NONDETERMINISTIC[self-host lane: {} distinct outputs over {} runs]",
            self_variants.len(),
            PARITY_ATTRIBUTION_SELF_RERUNS + 1,
        ));
    }

    let mut oracle_variants: Vec<String> = vec![oracle_stdout.to_string()];
    for _ in 0..PARITY_ATTRIBUTION_ORACLE_RERUNS {
        let Ok(out) = run_with_timeout_catching(
            Command::new(gg_exe).arg("run").arg(fixture).stdin(Stdio::null()),
            stem,
        ) else {
            break;
        };
        if !out.status.success() {
            break;
        }
        let s = String::from_utf8_lossy(&out.stdout).trim_end().to_string();
        if !oracle_variants.contains(&s) {
            oracle_variants.push(s);
        }
    }
    if oracle_variants.len() > 1 {
        return Some(format!(
            "NONDETERMINISTIC[Rust oracle: {} distinct outputs over {} runs]",
            oracle_variants.len(),
            PARITY_ATTRIBUTION_ORACLE_RERUNS + 1,
        ));
    }

    None
}

/// First-differing-line summary between an oracle and a self-host stdout.
fn first_diff_line(oracle: &str, mine: &str) -> String {
    oracle
        .lines()
        .zip(mine.lines())
        .enumerate()
        .find(|(_, (r, s))| r != s)
        .map(|(i, (r, s))| format!("L{i}: oracle={r:?} self={s:?}"))
        .unwrap_or_else(|| {
            format!(
                "line-count: oracle={} self={}",
                oracle.lines().count(),
                mine.lines().count(),
            )
        })
}

/// `run_with_timeout` PANICS when a child overruns the deadline. Inside a
/// `parallel_map_fixtures` worker that panic aborts the whole chunk — over the
/// full corpus, ONE infinite-loop / stdin-blocking fixture would take out every
/// result the worker accumulated. This wrapper catches the timeout panic and
/// returns `Err` so the caller can record a per-fixture outcome instead.
///
/// The default panic hook would still spew the "timed out" line to stderr; the
/// corpus-level entry points install a silent hook for the duration (see
/// `with_silent_panic_hook`). `AssertUnwindSafe` is sound here: the closure
/// only spawns a subprocess and reads its output — no shared mutable state
/// crosses the unwind boundary.
///
/// Returns `Err(panic_message)` on a caught panic so the caller can tell a
/// prompt runaway-output kill (~one poll tick past the cap) apart from a
/// full-deadline timeout — otherwise a 2-second output-kill reads as an Ns
/// "timed out" in the CRASH backlog. The message is the `panic!` string from
/// `run_with_deadline` ("… runaway output (>N bytes) — killed" vs "… timed out
/// after Ns"); callers that don't care about the reason ignore it.
fn run_with_timeout_catching(cmd: &mut Command, fixture: &str) -> Result<std::process::Output, String> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        run_with_timeout(cmd, fixture)
    })) {
        Ok(out) => Ok(out),
        Err(payload) => {
            let msg = payload
                .downcast_ref::<String>()
                .cloned()
                .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
                .unwrap_or_else(|| "panicked (no message)".to_string());
            Err(msg)
        }
    }
}

/// Run `f` with the default panic hook suppressed, restoring it after. Used by
/// the corpus-level runtime-parity entry points (A `self_host_runtime_diff` and
/// the regen path) so the expected per-fixture timeout panics (caught by
/// `run_with_timeout_catching`) don't flood the report with backtrace noise.
/// NOT re-entrant across threads — call it ONCE around the whole
/// `parallel_map_fixtures` body, never per-fixture (the hook is process-global
/// and a per-fixture swap would race across workers).
///
/// Restoration is RAII: the previous hook is captured in a Drop guard, so it is
/// ALWAYS restored — even if `f` panics on a non-caught path (e.g. a
/// `parallel_map_fixtures` worker re-panics). A bare set/restore around `f()`
/// would leak the silent hook on such a panic, swallowing every subsequent
/// panic message in the process.
fn with_silent_panic_hook<R>(f: impl FnOnce() -> R) -> R {
    struct HookGuard {
        prev: Option<Box<dyn Fn(&std::panic::PanicHookInfo<'_>) + Sync + Send>>,
    }
    impl Drop for HookGuard {
        fn drop(&mut self) {
            if let Some(prev) = self.prev.take() {
                std::panic::set_hook(prev);
            }
        }
    }

    let _guard = HookGuard { prev: Some(std::panic::take_hook()) };
    std::panic::set_hook(Box::new(|_| {}));
    f()
    // `_guard` drops here (or on unwind), restoring the previous hook.
}

/// Build a fixture through the self-host driver (`F lib --emit-c`) → `cc` →
/// run, returning the trimmed stdout on success or a non-Match outcome on any
/// failure. `tmp_root` must already exist; the caller owns its cleanup.
fn self_host_emit_cc_run(
    driver_exe: &Path,
    lib_dir: &Path,
    runtime_dir: &Path,
    fixture: &Path,
    tmp_root: &Path,
    tag: &str,
) -> Result<String, RuntimeParityOutcome> {
    let fname = fixture.file_name().unwrap().to_string_lossy().to_string();
    let stem = fixture.file_stem().unwrap().to_string_lossy().to_string();
    let c_path = tmp_root.join(format!("{stem}_{tag}.c"));
    let bin_path = self_host_bin_path(tmp_root, &stem, tag);

    // Self-host: driver F lib --emit-c --runtime-dir=<abs>.
    let emit = run_with_timeout(
        Command::new(driver_exe)
            .arg(fixture)
            .arg(lib_dir)
            .arg("--emit-c")
            .arg(format!("--runtime-dir={}", runtime_dir.display())),
        &fname,
    );
    if !emit.status.success() {
        let stderr = String::from_utf8_lossy(&emit.stderr);
        return Err(RuntimeParityOutcome::DriverFailed {
            detail: stderr.lines().next().unwrap_or("(no stderr)").chars().take(200).collect(),
        });
    }
    let full_c = String::from_utf8_lossy(&emit.stdout).to_string();
    if let Err(e) = std::fs::write(&c_path, &full_c) {
        return Err(RuntimeParityOutcome::CcFailed { detail: format!("write .c failed: {e}") });
    }

    let cc_out = Command::new("cc")
        .arg("-O0").arg("-w")
        .arg("-o").arg(&bin_path)
        .arg(&c_path)
        .arg("-lm")
        .arg("-lpthread")
        .output();
    let cc_out = match cc_out {
        Ok(o) => o,
        Err(e) => {
            return Err(RuntimeParityOutcome::CcFailed { detail: format!("spawn cc: {e}") });
        }
    };
    if !cc_out.status.success() {
        let stderr = String::from_utf8_lossy(&cc_out.stderr);
        let first = stderr
            .lines()
            .find(|l| l.contains("error") || l.contains("undefined"))
            .or_else(|| stderr.lines().next())
            .unwrap_or("(no stderr)")
            .chars().take(200).collect::<String>();
        return Err(RuntimeParityOutcome::CcFailed { detail: first });
    }

    // `run_with_timeout` PANICS on a hung binary. Over the full corpus a single
    // infinite-loop / stdin-blocking fixture would abort the whole parallel
    // worker (and with it every result it accumulated). Isolate it: a timeout
    // becomes a Crashed("timed out") outcome for THIS fixture, not a fatal
    // abort.
    //
    // Null the child's stdin: stdin-reading fixtures (e.g. io_input.gg) would
    // otherwise inherit the parent sweep's stdin, which never EOFs under the
    // parallel harness, and block in `read_line` until the deadline. With
    // `Stdio::null()` they get immediate EOF and produce their EOF-path output
    // (matching the committed snapshot), so the full sweep is clean without a
    // `< /dev/null` redirect on the cargo invocation.
    let mut run_cmd = Command::new(&bin_path);
    run_cmd.stdin(Stdio::null());
    let run = match run_with_timeout_catching(&mut run_cmd, &fname) {
        Ok(out) => out,
        Err(msg) => {
            // Honest label: a runaway-output kill fires ~one poll tick past the
            // cap, NOT at the deadline — don't file it as an Ns timeout.
            let stderr_first = if msg.contains("runaway output") {
                format!("runaway output — killed (>{}MiB)", MAX_CAPTURE_BYTES / (1024 * 1024))
            } else {
                format!("timed out after {}s", test_binary_timeout().as_secs())
            };
            return Err(RuntimeParityOutcome::Crashed { exit_code: None, stderr_first });
        }
    };
    if !run.status.success() {
        let stderr = String::from_utf8_lossy(&run.stderr);
        return Err(RuntimeParityOutcome::Crashed {
            exit_code: run.status.code(),
            stderr_first: stderr.lines().next().unwrap_or("(no stderr)").chars().take(200).collect(),
        });
    }
    Ok(String::from_utf8_lossy(&run.stdout).trim_end().to_string())
}

/// Assert a fixture's stdout **on the SELF-HOST lane**: emit C with the
/// self-host driver, `cc` it, run it, compare.
///
/// **Use this, not `run_gg`, whenever the filed gap lives on the SH lane.**
/// `run_gg` drives Rust gg, so a test parked for an SH-lane defect that calls
/// it asserts the lane that is *already correct*: it is green the day it is
/// written and green the day the gap is fixed, so its `#[ignore]` guards
/// nothing (Core #12, "green on arrival is not coverage"). R44's census
/// measured eight such tests — every one of them passing, none of them a
/// graduation — which is why this helper exists instead of an eighth copy of
/// the same thirty lines (Core #4: centralize at the producer).
///
/// ⚠ PARTIAL EXTRACTION, and nothing forces the next test through it. The ten
/// known_gaps SH-lane tests route here, but `self_host_emit_cc_run` still has
/// ~21 other call sites in this file, several of them the identical
/// `build_gg_dir_cached` -> `tmp_root` -> `match { Ok => assert_eq!, Err =>
/// panic! }` shape. There is no arm-count lint, so a new SH-lane test can still
/// be a paste. Converting the mechanical ones is filed in TODO.md; until it
/// lands, "use this helper" is a convention, not a guard.
///
/// `tag` disambiguates the scratch directory; keep it short and unique.
/// A driver failure, `cc` failure, crash or timeout panics with the outcome —
/// which is the *correct* red for a still-open SH gap.
fn assert_self_host_stdout(fixture_rel: &str, tag: &str, expected: &str) {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");
    let fixture = manifest_dir.join("tests/fixtures").join(fixture_rel);
    assert!(fixture.exists(), "Fixture not found: {}", fixture.display());

    let tmp_root = std::env::temp_dir().join(format!("gg_sh_{tag}_{}", std::process::id()));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");
    let result = self_host_emit_cc_run(
        &driver_exe, &lib_dir, &runtime_dir, &fixture, &tmp_root, "sh",
    );
    let _ = std::fs::remove_dir_all(&tmp_root);

    match result {
        Ok(stdout) => assert_eq!(
            stdout.trim(),
            expected.trim(),
            "SELF-HOST lane output mismatch for {fixture_rel}",
        ),
        Err(outcome) => panic!("self-host emit/cc/run failed for {fixture_rel}: {outcome:?}"),
    }
}

// ══════════════════════════════════════════════════════════════════════════
// R44 Track K — the self-host COMPREHENSION net
// ══════════════════════════════════════════════════════════════════════════
//
// `tests/fixtures/self_host_comprehension/` holds one CELL PER FILE, each
// beside a `<stem>.expected` sidecar carrying its exact expected stdout. Every
// cell's header records which CELL OF WHICH AXIS it samples, the RED it was
// verified against, and its PLACEMENT / LANE / STAGE / RUNG.
//
// ── Why a SUBDIRECTORY, not top-level `tests/fixtures/` ───────────────────
// Top-level enrolment is automatic and directory-driven, so 39 new cells
// would land at once in: `runtime_parity_corpus` and its
// `RUNTIME_DIFF_NONMATCH_CEILING` (Core #9 ⊕ forbids raising that for a
// round's OWN inflow); the sanitize sweep, whose corpus is the top-level
// `*.gg` plus every directory `tests/sanitize/CORPUS_MANIFEST.txt` marks `IN`
// (this directory's row is `OUT`, and it cites this reason); and the
// shrink-only leak allowlist, where a leaking top-level cell cannot be
// allowlisted without an owner ruling. A subdirectory also makes SELF-HOST-ONLY wiring expressible, which is
// what the lane disposition below needs. ⚠ This is a property of THESE cells,
// not a general rule — decide per fixture.
//
// ── Why SELF-HOST-ONLY ────────────────────────────────────────────────────
// This round changes no accept/reject and no accepted program's meaning: it
// makes the self-host agree with an already-correct Rust lane. That is Core
// #9's *implementation-internal* exemption (lanes share semantics, not
// implementation), cited by name — NOT a silent lane gap. The Rust column was
// measured for every cell while the `.expected` values were minted, and every
// value except one IS a post-fix Rust==self-host agreement. The exception is
// `list_bytessrc_narrow_elem`, where the RUST lane is the wrong one; its
// header says so and the Rust half is separately filed with its own durable
// repro and `#[ignore]`d test.
//
// ── Why DIRECTORY-DRIVEN rather than one named test per cell ──────────────
// A new cell dropped into the directory is enrolled automatically — there is
// no "forgot to wire it" hole, which is the failure mode a hand-written list
// of 35 `#[test]` fns actually has. Per-cell verdicts survive: every cell gets
// its own emit / cc / run, and every failure is reported by cell name, so a
// co-resident failure cannot destroy a healthy cell's evidence (which is the
// property DEC-K3-6's "one cell per FILE" exists to protect).
//
// The guard below can catch its own class (Core #15e Q2): a `.gg` without an
// `.expected` FAILS rather than being skipped, and the cell count has a
// shrink-only floor so silently deleting the net is a red.

/// Cell count floor for `tests/fixtures/self_host_comprehension/`.
///
/// SHRINK-ONLY IN THE WRONG DIRECTION: raise it when the net grows, never
/// lower it to make a red go away. A net that can be emptied without a test
/// failing is not a net.
const SELF_HOST_COMPREHENSION_CELL_FLOOR: usize = 39;

/// The self-host COMPREHENSION net, stage 0.
///
/// Each cell is emitted by the self-host driver, `cc`'d, run, and its trimmed
/// stdout compared against its committed `.expected`.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_comprehension_net() {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");
    let cells_dir = manifest_dir.join("tests/fixtures/self_host_comprehension");

    let mut cells: Vec<PathBuf> = std::fs::read_dir(&cells_dir)
        .unwrap_or_else(|e| panic!("self_host_comprehension dir unreadable: {e}"))
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.is_file() && p.extension().map_or(false, |x| x == "gg"))
        .collect();
    cells.sort();

    assert!(
        cells.len() >= SELF_HOST_COMPREHENSION_CELL_FLOOR,
        "self_host_comprehension: {} cells, floor is {}. Cells were DELETED. \
         The floor is shrink-only in the wrong direction — raise it when the \
         net grows, never lower it to clear a red.",
        cells.len(),
        SELF_HOST_COMPREHENSION_CELL_FLOOR,
    );

    // Every cell must carry an expectation. A `.gg` with no `.expected` is a
    // cell that would otherwise be silently skipped — the exact shape of a
    // guard that cannot catch its own class.
    let missing: Vec<String> = cells
        .iter()
        .filter(|p| !p.with_extension("expected").exists())
        .map(|p| p.file_name().unwrap().to_string_lossy().to_string())
        .collect();
    assert!(
        missing.is_empty(),
        "self_host_comprehension: {} cell(s) have no `.expected` sidecar and would \
         be silently unchecked: {}",
        missing.len(),
        missing.join(", "),
    );

    let tmp_root = std::env::temp_dir().join(format!("gg_shcomp_{}", std::process::id()));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");

    let driver_exe = &driver_exe;
    let lib_dir = &lib_dir;
    let runtime_dir = &runtime_dir;
    let tmp_root = &tmp_root;

    let failures: Vec<String> = parallel_map_fixtures(&cells, |cell| {
        let stem = cell.file_stem().unwrap().to_string_lossy().to_string();
        let expected = match std::fs::read_to_string(cell.with_extension("expected")) {
            Ok(s) => s.trim().to_string(),
            Err(e) => return Some(format!("{stem}: .expected read failed: {e}")),
        };
        match self_host_emit_cc_run(driver_exe, lib_dir, runtime_dir, cell, tmp_root, "shcomp") {
            Ok(stdout) => {
                if stdout.trim() == expected {
                    None
                } else {
                    Some(format!(
                        "{stem}: WRONG-OUTPUT (expected {:?}, got {:?})",
                        expected,
                        stdout.trim(),
                    ))
                }
            }
            Err(outcome) => Some(format!("{stem}: {outcome:?}")),
        }
    })
    .into_iter()
    .flatten()
    .collect();

    let _ = std::fs::remove_dir_all(tmp_root);

    assert!(
        failures.is_empty(),
        "self_host_comprehension: {} of {} cell(s) failed:\n  {}",
        failures.len(),
        cells.len(),
        failures.join("\n  "),
    );
}

/// Build a STAGE-1 self-host binary: the self-host compiler compiled BY
/// ITSELF. Factored out of `run_bootstrap_stages`'s first half — that
/// function deletes its stage-1 binary at four sites, so a caller that wants
/// to RUN one has to build its own.
///
/// Returns the stage-1 executable's path inside `work_dir`.
fn build_stage1_driver(
    driver_exe: &Path,
    driver_c: &Path,
    driver_gg: &Path,
    lib_dir: &Path,
    work_dir: &Path,
) -> Result<PathBuf, String> {
    let _ = std::fs::create_dir_all(work_dir);

    let body_out = run_with_deadline(
        Command::new(driver_exe).arg(driver_gg).arg(lib_dir).arg("--lir-c"),
        "build_stage1_driver stage0 -> stage1.c",
        Duration::from_secs(env_or_load_adjusted_secs("GG_STAGE1_TIMEOUT_SECS", 600)),
    );
    if !body_out.status.success() {
        return Err(format!(
            "stage-0 driver failed: stderr={}",
            String::from_utf8_lossy(&body_out.stderr),
        ));
    }
    let stage1_body = String::from_utf8_lossy(&body_out.stdout).to_string();

    let rust_c = std::fs::read_to_string(driver_c)
        .map_err(|e| format!("failed to read driver.c at {}: {e}", driver_c.display()))?;
    let preamble_end = rust_c
        .find("\ntypedef struct __gg_")
        .ok_or_else(|| "driver.c has no user-type typedef boundary".to_string())?;
    let runtime_preamble = &rust_c[..preamble_end];

    let stage1_c = work_dir.join("shcomp_stage1.c");
    let stage1_bin = work_dir.join("shcomp_stage1");
    std::fs::write(&stage1_c, format!("{runtime_preamble}\n{stage1_body}"))
        .map_err(|e| format!("failed to write stage1.c: {e}"))?;

    let cc_out = Command::new("cc")
        .arg("-O0").arg("-w")
        .arg("-o").arg(&stage1_bin)
        .arg(&stage1_c)
        .arg("-lm").arg("-lpthread")
        .output()
        .map_err(|e| format!("failed to spawn cc: {e}"))?;
    if !cc_out.status.success() {
        return Err(format!("stage-1 cc failed: {}", String::from_utf8_lossy(&cc_out.stderr)));
    }
    Ok(stage1_bin)
}

/// The STAGE-1 half of the comprehension net — the only instrument in this
/// tree that can see its class.
///
/// ⚠ WHY THIS TEST HAS TO EXIST. Every other self-host gate runs the STAGE-0
/// driver (the one Rust gg built), and `self_host_bootstrap_fixed_point`
/// compares emitted C *text*, not behaviour. A defect that only appears once
/// the compiler compiles itself is therefore invisible to all of them. That
/// is not hypothetical. MEASURED on a pristine-HEAD stage-1 build:
/// `stage1_list_strsrc_filt` is GREEN at stage 0 (`2/a`) and rc 101 printing
/// `0` at stage 1; the round's rework of the filter path takes stage 1 to
/// `2/a`.
///
/// The MECHANISM is pinned, and it is not "a boxed parameter": the self-host
/// lowerer DOUBLE-FREES on `(*b).clone()` where `b` was bound by
/// `case Some(b)` on an `Option[Box[T]]`, and the pre-fix filter path spelled
/// exactly `(*filt_box).clone()`. Durable repro
/// `known_gaps/sh_option_box_deref_clone_double_free.gg` (rc 134 on the
/// self-host lane, correct on Rust); the compiler defect is UNFIXED and filed
/// in `TODO.md` (grep `stage-1-only`).
///
/// ⚠ Ablation handle, if you ever need to see this test earn its keep: change
/// `lower_expr.gg`'s set arm from `sv_fe = *sv_fb` to `sv_fe = (*sv_fb).clone()`
/// — `self_host_comprehension_net` stays green on all 39 stage-0 cells and THIS
/// test goes RED on `stage1_set_strsrc_filt` (`0/false/false` for
/// `2/true/true`). Measured.
///
/// The two cells sample DIFFERENT dispatcher arms (list/vector and set) on
/// purpose, so the pair is provably not one cell twice.
///
/// Cost: one stage-1 build (~2 min) plus two emit/cc/run.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_comprehension_stage1_net() {
    let (driver_exe, driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let runtime_dir = manifest_dir.join("src/backend/c/runtime");
    let driver_gg = manifest_dir.join("tests/fixtures/self_host_lowerer/driver.gg");
    let cells_dir = manifest_dir.join("tests/fixtures/self_host_comprehension");

    // The stage-1 cells, named by FILENAME (never by description).
    const STAGE1_CELLS: [&str; 2] = ["stage1_list_strsrc_filt", "stage1_set_strsrc_filt"];

    let work_dir = std::env::temp_dir().join(format!("gg_shcomp_s1_{}", std::process::id()));
    let stage1_bin = match build_stage1_driver(&driver_exe, &driver_c, &driver_gg, &lib_dir, &work_dir) {
        Ok(p) => p,
        Err(e) => {
            let _ = std::fs::remove_dir_all(&work_dir);
            panic!("self_host_comprehension_stage1_net: stage-1 build failed: {e}");
        }
    };

    let mut failures: Vec<String> = Vec::new();
    for stem in STAGE1_CELLS {
        let cell = cells_dir.join(format!("{stem}.gg"));
        assert!(cell.exists(), "stage-1 cell missing: {}", cell.display());
        let expected = std::fs::read_to_string(cells_dir.join(format!("{stem}.expected")))
            .unwrap_or_else(|e| panic!("{stem}: .expected read failed: {e}"))
            .trim()
            .to_string();

        // Same CLI as the stage-0 driver: `<bin> F lib --emit-c --runtime-dir=<abs>`.
        match self_host_emit_cc_run(&stage1_bin, &lib_dir, &runtime_dir, &cell, &work_dir, "s1") {
            Ok(stdout) => {
                if stdout.trim() != expected {
                    failures.push(format!(
                        "{stem}: STAGE-1 WRONG-OUTPUT (expected {:?}, got {:?})",
                        expected,
                        stdout.trim(),
                    ));
                }
            }
            Err(outcome) => failures.push(format!("{stem}: STAGE-1 {outcome:?}")),
        }
    }

    let _ = std::fs::remove_dir_all(&work_dir);

    assert!(
        failures.is_empty(),
        "self_host_comprehension_stage1_net: {} cell(s) failed on the STAGE-1 \
         binary (they may well be green on the stage-0 driver — that is exactly \
         the class this test exists for):\n  {}",
        failures.len(),
        failures.join("\n  "),
    );
}

/// Assert the self-host driver REJECTS a comprehension whose source lowered no
/// loop — loudly, on stderr, with no emitted C.
///
/// ⚠ `assert_self_host_stdout` cannot express a reject row, so this follows
/// the `self_host_driver_rejects_*` template. ⚠ Its stdout assertion is
/// deliberately NOT "empty": `lower_fail` writes its marker to STDOUT (it
/// lands inside the emitted C as a comment), so a rejected program's stdout
/// legitimately carries that marker. What must be absent is emitted C.
fn assert_self_host_rejects_comprehension(fixture_rel: &str, tag: &str) {
    let (driver_exe, _driver_c) = build_gg_dir_cached("self_host_lowerer", "driver.gg");
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let lib_dir = manifest_dir.join("lib");
    let fixture = manifest_dir.join("tests/fixtures").join(fixture_rel);
    assert!(fixture.exists(), "reject fixture missing: {}", fixture.display());

    let out = run_with_timeout(
        Command::new(&driver_exe).arg(&fixture).arg(&lib_dir).arg("--lir-c"),
        tag,
    );
    let stderr = String::from_utf8_lossy(&out.stderr);
    let stdout = String::from_utf8_lossy(&out.stdout);

    assert!(
        !out.status.success(),
        "self-host driver ACCEPTED {fixture_rel} — a comprehension whose source \
         lowered no loop must FAIL THE BUILD (Core #10 lower-or-reject), not \
         return an unconstructed placeholder and print an empty collection at \
         rc 0. exit={:?}\nstdout head:\n{}\nstderr:\n{stderr}",
        out.status.code(),
        &stdout.chars().take(300).collect::<String>(),
    );
    assert!(
        stderr.contains("cannot lower a comprehension"),
        "self-host driver exited non-zero on {fixture_rel} but printed no \
         comprehension diagnostic to STDERR. The diagnostic must go to stderr: \
         the tree's other in-lowerer abort writes to STDOUT, which would bury \
         it inside the emitted C.\nstderr:\n{stderr}",
    );
    assert!(
        !stdout.contains("int main("),
        "self-host driver emitted C for a rejected program — the abort must \
         halt BEFORE the module finishes lowering.\nstdout head:\n{}",
        &stdout.chars().take(300).collect::<String>(),
    );
}

/// REJECT ROW — a comprehension over a struct with no iterator.
///
/// AXIS CELL: source = a plain `struct` (no `iter()`/`next()` pair).
/// Adjudicated by Core #10 (lower-or-reject), NEVER by a run of any form: the
/// value a run produces here is `0`, which is the silently-empty collection
/// this arm exists to eliminate, so copying it would be voting for the defect.
///
/// RED-VERIFIED on the pre-fix self-host driver: rc 0, stdout `0`. Rust gg
/// already panics (rc 101) with the matching message — the SH lane was the
/// lagging one, which is why this pin is wired here.
///
/// ⚠ The underlying front-end gap (no is-it-iterable gate; `gg check` accepts
/// this program on every lane) is SEPARATELY FILED and is NOT what this test
/// pins. A compiler abort is not the reference-grade answer — a check-time
/// rejection is. This test pins only that the self-host lowerer refuses to
/// trade a loud failure for a silent one.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_rejects_comprehension_over_non_iterable_struct() {
    assert_self_host_rejects_comprehension(
        "known_gaps/comprehension_over_non_iterable_struct.gg",
        "self_host_rejects_comprehension_over_non_iterable_struct",
    );
}

/// REJECT ROW — a comprehension over a `Heap[T]`.
///
/// AXIS CELL: source = `CkHeap`, the `CollectionKind` variant the dispatcher's
/// cascade `else` swallows. It is a SECOND SHAPE of the already-filed
/// no-is-it-iterable-gate class (a `Heap` has no `iter()`/`next()` pair
/// either), NOT a second filing — which is why it ships as a repro under the
/// existing bullet rather than a new one.
///
/// RED-VERIFIED on the pre-fix self-host driver: rc 0, stdout `0` / `done` —
/// a silently empty collection. Rust gg panics (rc 101). ⚠ And the STATEMENT
/// form of the same iteration prints `0` SILENTLY on the Rust lane too, which
/// is the second defect Core #8 names; that half stays with the filed bullet.
#[test]
#[serial(self_host_lowerer_driver)]
fn self_host_rejects_comprehension_over_heap() {
    assert_self_host_rejects_comprehension(
        "known_gaps/comprehension_over_heap_source.gg",
        "self_host_rejects_comprehension_over_heap",
    );
}

/// Full corpus of `.gg` fixtures (read_dir + ext=="gg" + sort), mirroring the
/// corpus enumeration in `c_emit_comparison`.
fn runtime_parity_corpus(manifest_dir: &Path) -> Vec<PathBuf> {
    let fixtures_dir = manifest_dir.join("tests/fixtures");
    let mut fixtures: Vec<PathBuf> = std::fs::read_dir(&fixtures_dir)
        .expect("failed to read fixtures dir")
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.is_file() && p.extension().map_or(false, |ext| ext == "gg"))
        .collect();
    fixtures.sort();
    fixtures
}

/// Regression for the `Vector[Option[T]].fill(n, None)` bare-None SEGV /
/// miscompile (Core #8, R36-C on Rust; R37-T4 on the self-host).
///
/// Sibling of the `collection_bare_none_value.gg` shared fixture: the value-arg
/// expected-type hint (`methods.rs` `value_arg_idx_for_method` on Rust; the
/// `fill` row in `COLLECTION_BUILTIN_METHODS` + the LAST-arg hint derivation on
/// the self-host) now covers `fill`, so a bare `None` in the fill value
/// position materialises as a tagged `None` instead of `Constant::Null`. Before
/// the fix, Rust did a memcpy FROM the null pointer → SEGV (exit 139); the
/// self-host lowered the None to int32 0 → bogus `Some(0)`.
///
/// Both compilers now agree on `fill_bare_none.gg`, so it is a real
/// `tests/fixtures/*.gg` fixture auto-scanned into `runtime_parity_corpus`
/// (the self-host grew the hint-WITHOUT-consume path: the `fill` row carries an
/// EMPTY `owning_arg_positions`, so `fill(2, live_string)` is ASan-clean — no
/// double-free). This inline `run_gg` keeps the fast direct assertion.
/// (`get_or_put(k, None)` still diverges on a deeper `__gg_Option__int64_t`
/// self-host type-registration bug — that flip stays filed as a follow-up.)
#[test]
fn collection_fill_bare_none() {
    run_gg("fill_bare_none.gg", "3\ntrue\ntrue\ntrue");
}

/// RUST-ONLY regression for the R37-T1 self-host CoW under-materialize: a
/// NAMED-receiver USER `&self` mutator invoked on a BARE by-value param must
/// leave the caller's value untouched (CoW-default-borrow: the callee's `Res`
/// is a private copy). Rust gg gets this right — `mutate(a)` prints the copy's
/// `"Y"` while `main` still sees `"A"`.
///
/// KNOWN SELF-HOST DIVERGENCE (filed, do NOT force-fix): the self-host lowerer
/// (`self_host_lowerer/lower_expr.gg`, R37-T1) deliberately narrows the
/// CoW-materialize on a mutating METHOD receiver to BUILTIN-any + USER-PROJECTED
/// receivers only. A named-receiver USER `&self` call (`x.set_name("Y")` on a
/// bare param) is NOT materialized, so the self-host WRITES THROUGH and prints
/// `Y / Y / done` where Rust prints `Y / A / done`. The narrowing is
/// load-bearing: Gorget's `&self` is a MUTABLE borrow, so the self-host cannot
/// tell a read-only `&self` (`sexpr.clone()`, getters — called constantly in the
/// driver) from a mutating one; materializing on EVERY named user-`&self`
/// receiver deep-clones the whole receiver root per call — a measured ~14 GB
/// clone bomb that OOM-kills `self_host_bootstrap_fixed_point`. The real fix
/// needs a `&self` MUTATION-INFERENCE pass (classify each `&self` method
/// read-only vs mutating, materialize only for the mutating ones). Filed in
/// TODO.md.
///
/// Why this is NOT a `tests/fixtures/*.gg` fixture: `runtime_parity_corpus`
/// auto-scans every `tests/fixtures/*.gg`, so a fixture here would force
/// self-host agreement and count as a permanent WRONG in `self_host_runtime_diff`
/// (and the `cow_*` sweep). Until the self-host grows the `&self`
/// mutation-inference pass, this named-receiver case cannot enter the
/// both-compilers-must-agree corpus, so this Rust-only inline test carries the
/// correct-expected-output regression instead.
#[test]
fn rust_named_recv_user_mutator_caller_untouched() {
    let gg_exe: PathBuf = gg_binary().to_path_buf();
    let tmp_root = std::env::temp_dir().join(format!(
        "gg_named_recv_wt_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");
    let src = tmp_root.join("named_recv_writethrough.gg");
    std::fs::write(
        &src,
        "struct Res:\n\
        \x20   String name\n\
        \n\
        equip Res:\n\
        \x20   void set_name(&self, String n):\n\
        \x20       self.name = n\n\
        \n\
        void mutate(Res x):\n\
        \x20   x.set_name(\"Y\")\n\
        \x20   print(x.name)\n\
        \n\
        void main():\n\
        \x20   Res a = Res(\"A\")\n\
        \x20   mutate(a)\n\
        \x20   print(a.name)\n\
        \x20   print(\"done\")\n",
    )
    .expect("failed to write named_recv_writethrough.gg");

    let run = run_with_timeout(
        Command::new(&gg_exe).arg("run").arg(&src).stdin(Stdio::null()),
        "run named_recv_writethrough.gg",
    );
    let _ = std::fs::remove_dir_all(&tmp_root);

    assert!(
        run.status.success(),
        "`gg run` on a named-receiver user `&self` mutator should exit 0; got {:?}.\nstderr: {}",
        run.status.code(),
        String::from_utf8_lossy(&run.stderr),
    );
    assert_eq!(
        String::from_utf8_lossy(&run.stdout).trim_end(),
        "Y\nA\ndone",
        "a named-receiver user `&self` mutator on a bare by-value param must NOT \
         write through to the caller (CoW-default-borrow): the copy prints \"Y\", \
         the caller still prints \"A\". Self-host currently prints \"Y\\nY\\ndone\" \
         (filed, R37-T1 narrowed gate — see doc comment).",
    );
}

/// RUST reference-miscompile regression (Core #8, R39-T1 + solid-ground R1): a
/// field-store / mut-method whose object is an INDEX into a Vector of a VALUE-type
/// element (a struct of scalars) must WRITE THROUGH to the collection's heap
/// buffer. Before the fix, `v[0].x = 99` — and the `static`, compound
/// (`PTS[1].x += 100`), nested (`ns[0].inner.val = 99`), value-field-method-receiver
/// (`hs[0].c.bump()`), and bare Index method-receiver (`cs[0].bump()`) variants —
/// landed on a STACK COPY of the element and were silently dropped, so Rust gg
/// printed the STALE value on BOTH the C and LLVM backends. This was a Core #8
/// reference miscompile: a RESOURCE-typed element field already wrote through
/// (the old `lower_index_access` returned a `Ptr` handle only for resource
/// elements), which pinned the value-vs-resource asymmetry as the root. Fixed by
/// the `Expr::Index` arm in `try_resolve_field_place` (field path) and the shared
/// `try_resolve_index_element_ptr` producer used by bare Index mut method receivers
/// (forces `Ptr(T)` for value elements too) + the hoisted round-33 CoW untrack.
///
/// Corpus split (CoW Track 1B / Track V / Track X / Round XIX hygiene): the
/// SINGLE-LEVEL shapes — plain + compound value-element field stores on a LOCAL
/// and a STATIC Vector (`v[0].x = 88`, `v[1].y += 5`, `PTS[0].x = 99`,
/// `PTS[1].x += 100`) — are fixed in the self-host too and promoted to
/// `cow_value_index_field_writethrough.gg`. The bare Index METHOD-receiver
/// `cs[i].bump()` (const and non-const index) is promoted to
/// `cow_value_index_bare_mut_recv_writethrough.gg` after Track V. The
/// value-field-METHOD-receiver `hs[0].c.bump()` (EFieldAccess-of-EIndex, and its
/// deeper `ws[0].h.c.bump()` sibling) is promoted to
/// `cow_value_index_nested_mut_recv_writethrough.gg` after Track X. The NESTED
/// store `ns[0].inner.val = 99` is promoted to
/// `cow_value_index_nested_field_store.gg` after Round XIX hygiene (store face
/// MATCH on Rust + SH via `lower_amp_place`). This inline test is KEPT as a
/// multi-shape both-backend pin (static/local plain + compound + nested) —
/// asserting BOTH backends (the pre-fix miscompile reproduced on both).
#[test]
fn rust_value_index_element_field_writethrough() {
    let gg_exe: PathBuf = gg_binary().to_path_buf();
    let tmp_root = std::env::temp_dir().join(format!(
        "gg_val_idx_field_wt_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0),
    ));
    std::fs::create_dir_all(&tmp_root).expect("failed to create tmp_root");
    let src = tmp_root.join("value_index_field_writethrough.gg");
    std::fs::write(
        &src,
        concat!(
            "from std.collections import Vector\n",
            "\n",
            "struct Point:\n",
            "    int x\n",
            "    int y\n",
            "\n",
            "struct Inner:\n",
            "    int val\n",
            "\n",
            "struct Nest:\n",
            "    Inner inner\n",
            "    int tag\n",
            "\n",
            "static Vector[Point] PTS = [Point(1, 2), Point(3, 4)]\n",
            "\n",
            "void main():\n",
            "    PTS[0].x = 99\n",            // static value-element field store
            "    print(PTS[0].x)\n",          // 99
            "    print(PTS[1].x)\n",          // 3  (untouched)
            "    Vector[Point] v = [Point(10, 20), Point(30, 40)]\n",
            "    v[0].x = 88\n",              // local value-element field store
            "    print(v[0].x)\n",           // 88
            "    print(v[1].x)\n",           // 30
            "    PTS[1].x += 100\n",         // compound on static value element
            "    print(PTS[1].x)\n",         // 103
            "    v[1].y += 5\n",             // compound on local value element
            "    print(v[1].y)\n",           // 45
            "    Vector[Nest] ns = [Nest(Inner(1), 7), Nest(Inner(2), 8)]\n",
            "    ns[0].inner.val = 99\n",    // nested value-element field store
            "    print(ns[0].inner.val)\n",  // 99
            "    print(ns[1].inner.val)\n",  // 2
            "    print(\"done\")\n",
        ),
    )
    .expect("failed to write value_index_field_writethrough.gg");

    let expected = "99\n3\n88\n30\n103\n45\n99\n2\ndone";

    // Both backends must agree AND be correct — the pre-fix miscompile
    // reproduced identically on C and LLVM (this fix is in shared GIR lowering,
    // upstream of both backend emitters).
    for backend in [None, Some("--backend=llvm")] {
        let mut cmd = Command::new(&gg_exe);
        cmd.arg("run").arg(&src).stdin(Stdio::null());
        if let Some(flag) = backend {
            cmd.arg(flag);
        }
        let label = backend.unwrap_or("(c)");
        let run = run_with_timeout(&mut cmd, "run value_index_field_writethrough.gg");
        assert!(
            run.status.success(),
            "`gg run {label}` on a value-type index-element field-store should exit 0; got {:?}.\nstderr: {}",
            run.status.code(),
            String::from_utf8_lossy(&run.stderr),
        );
        assert_eq!(
            String::from_utf8_lossy(&run.stdout).trim_end(),
            expected,
            "value-type Vector index-element field-store / bare Index mut method \
             (plain / static / compound / nested / value-field-method-receiver / \
             bare-index-method / non-const-index) must WRITE THROUGH on backend {label} \
             (Core #8 reference miscompile: pre-fix Rust printed the stale value on BOTH backends).",
        );
    }
    let _ = std::fs::remove_dir_all(&tmp_root);
}

/// CoW Track 1B corpus fixture (C + LLVM lanes; the self-host lane auto-enrolls
