// ── Benchmark tests ──────────────────────────────────────────

/// Run `gg test --bench <fixture>` and check expected stdout fragments.
fn run_gg_bench(fixture: &str, expected_fragments: &[&str]) {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture_path = manifest_dir.join("tests/fixtures").join(fixture);

    assert!(
        fixture_path.exists(),
        "Fixture not found: {}",
        fixture_path.display()
    );

    let stem = fixture_path.file_stem().unwrap().to_str().unwrap();
    let dir = fixture_path.parent().unwrap();
    let c_path = dir.join(format!("{stem}.c"));
    let exe_path = dir.join(stem);

    let output = build_with_timeout(
        gg_command("test")
            .args(["--bench", fixture_path.to_str().unwrap()]),
        fixture,
    );

    let stdout = String::from_utf8_lossy(&output.stdout);

    for fragment in expected_fragments {
        assert!(
            stdout.contains(fragment),
            "Expected fragment {fragment:?} not found in bench output:\n{stdout}\nstderr: {}",
            String::from_utf8_lossy(&output.stderr),
        );
    }

    assert!(
        output.status.success(),
        "Expected success for bench {fixture} but got {:?}\nstdout: {stdout}\nstderr: {}",
        output.status.code(),
        String::from_utf8_lossy(&output.stderr),
    );

    let _ = std::fs::remove_file(&c_path);
    let _ = std::fs::remove_file(&exe_path);
}

#[test]
fn bench_basic() {
    run_gg_bench(
        "bench_basic.gg",
        &[
            "Running 2 benchmarks",
            "bench: addition",
            "iters",
            "ns/iter",
            "bench: string concat",
            "2 benchmarks complete",
        ],
    );
}

/// PATH CELL — the `bench` body (`lower_bench_items`), the fourth and last
/// module-loop body-lowering path. Like its three siblings in
/// `cow_test_body_view_survives_realloc` it ran a hand-copied SUBSET of the
/// per-function prescans (liveness only), so a CoW element view bound in a
/// bench body was never materialized before a reallocating push. Only
/// `gg test --bench` lowers this body. RED-verified: SIGSEGV pre-fix.
#[test]
fn cow_bench_body_view_survives_realloc() {
    run_gg_bench(
        "cow_bench_body_view_survives_realloc.gg",
        &["helloworld", "1 benchmark"],
    );
}

